// src/lib/firestore.js
import {
  collection, doc, getDoc, getDocs, addDoc, setDoc, query, where, orderBy, limit as fbLimit, serverTimestamp,
  writeBatch, runTransaction,
} from "firebase/firestore";
import { db } from "../firebase";

// ============================================================
// COLLECTION NAME RESOLVER
// ============================================================
const COLLECTION_OVERRIDES = {
  customers: "customer",
  customer: "customer",
  products: "products",
  product: "products",
  productmaster: "products",
  possettings: "possetting",
  possetting: "possetting",
  sales: "sales",
  sale: "sales",
  invoices: "sales",
  invoice: "sales",
  saleregister: "sales",
  locations: "location",
  location: "location",
  companies: "company",
  company: "company",
  suppliers: "supplier",
  supplier: "supplier",
  departments: "department",
  department: "department",
  categories: "category",
  category: "category",
  subcategories: "subcategory",
  subcategory: "subcategory",
  promotions: "promotion",
  promotion: "promotion",
  loyaltycategories: "loyaltycategories",
  loyaltycustomers: "customer",
  accounts: "accounts",
};

export function resolveCollectionName(name) {
  const raw = String(name ?? "").trim();
  if (!raw) return raw;
  const lower = raw.toLowerCase();
  if (COLLECTION_OVERRIDES[lower]) return COLLECTION_OVERRIDES[lower];
  if (COLLECTION_OVERRIDES[raw]) return COLLECTION_OVERRIDES[raw];

  if (raw.includes("/")) {
    return raw
      .split("/")
      .map((part, idx) => (idx % 2 === 0 ? (COLLECTION_OVERRIDES[part.toLowerCase()] || part.toLowerCase()) : part))
      .join("/");
  }

  return lower;
}

if (typeof process !== "undefined" && process.env?.NODE_ENV !== "production") {
  // eslint-disable-next-line no-console
  console.log(
    "[firestore] Collection names are normalised to lowercase. " +
    "If a collection appears empty, verify its name in Firestore Console."
  );
}

// ---------- READ ----------
// NOTE on `withMeta`:
//   - withMeta: true  → include docs where `_meta === true` (returns everything).
//   - withMeta: false → exclude docs where `_meta === true` (returns only data docs).
// The filter runs *client-side* after `getDocs`, so when `limit` is combined
// with `withMeta: false` the final result may contain fewer than `limit` rows
// if some of the top-N docs are `_meta` markers. If you need an exact count,
// filter the docs out of the query itself.
export async function listCollection(
  name,
  { where: wheres = [], orderBy: ob, limit, withMeta = false } = {}
) {
  const collName = resolveCollectionName(name);
  const constraints = [];
  for (const [field, op, value] of wheres) {
    constraints.push(where(field, op, value));
  }
  if (ob)    constraints.push(orderBy(ob.field, ob.dir || "asc"));
  if (limit) constraints.push(fbLimit(limit));

  const snap = await getDocs(query(collection(db, collName), ...constraints));
  return snap.docs
    .filter((d) => withMeta || d.data()._meta !== true)
    .map((d) => ({ id: d.id, ...d.data() }));
}

export async function readDoc(name, id) {
  const collName = resolveCollectionName(name);
  const snap = await getDoc(doc(db, collName, String(id)));
  return snap.exists() ? { id: snap.id, ...snap.data() } : null;
}

export const getDocById = readDoc;

// ---------- WRITE ----------
export async function createDoc(name, data, { customId, username } = {}) {
  const collName = resolveCollectionName(name);
  const payload = {
    ...data,
    CreatedDate:  serverTimestamp(),
    ModifiedDate: serverTimestamp(),
    ...(username && { CreatedUser: username, ModifiedUser: username }),
  };
  if (customId) {
    await setDoc(doc(db, collName, String(customId)), payload, { merge: true });
    return String(customId);
  }
  const ref = await addDoc(collection(db, collName), payload);
  return ref.id;
}

export async function updateDocById(name, id, data, { username } = {}) {
  const collName = resolveCollectionName(name);
  await setDoc(doc(db, collName, String(id)), {
    ...data,
    ModifiedDate: serverTimestamp(),
    ...(username && { ModifiedUser: username }),
  }, { merge: true });
}

export async function softDeleteDoc(name, id, { username } = {}) {
  const collName = resolveCollectionName(name);
  await setDoc(doc(db, collName, String(id)), {
    IsDelete: 1,
    IsActive: 0,
    ModifiedDate: serverTimestamp(),
    ...(username && { ModifiedUser: username }),
  }, { merge: true });
}

// ---------- BATCH WRITE ----------
export async function batchWrite(input) {
  const batch = writeBatch(db);

  if (typeof input === "function") {
    await input(batch);
    await batch.commit();
    return;
  }

  if (!Array.isArray(input)) {
    throw new Error("batchWrite: expected an array of ops or a callback");
  }

  for (const op of input) {
    const { type, collection: coll, id, data, options } = op;
    const collName = resolveCollectionName(coll);
    const ref = id ? doc(db, collName, String(id)) : doc(collection(db, collName));
    if      (type === "set")    batch.set(ref, data, options);
    else if (type === "update") batch.update(ref, data);
    else if (type === "delete") batch.delete(ref);
    else throw new Error(`batchWrite: unknown op "${type}"`);
  }

  await batch.commit();
}

// ---------- TRANSACTION ----------
export async function runFirestoreTransaction(fn) {
  return runTransaction(db, fn);
}

// ---------- CODE GENERATORS ----------
async function nextNumericCode(collectionName, field, prefix, pad) {
  const rows = await listCollection(collectionName, {
    orderBy: { field, dir: "desc" },
    limit: 1,
  });
  const last = Number(String(rows[0]?.[field] || "0").replace(/\D/g, "")) || 0;
  return `${prefix}${String(last + 1).padStart(pad, "0")}`;
}

export const nextDepartmentCode  = () => nextNumericCode("Department",    "DepartmentCode",   "D",   3);
export const nextCategoryCode    = () => nextNumericCode("Category",      "CategoryCode",     "C",   3);
export const nextSubCategoryCode = () => nextNumericCode("SubCategory",   "SubCategoryCode",  "",    3);
export const nextSupplierCode    = () => nextNumericCode("Supplier",      "SupplierCode",     "S",   4);
export const nextCompanyCode     = () => nextNumericCode("Company",       "CompanyCode",      "",    2);
export const nextLocationCode    = () => nextNumericCode("Location",      "LocationCode",     "",    2);
export const nextEmployeeCode    = () => nextNumericCode("Employee",      "EmployeeCode",     "EMP", 3);
export const nextSalesPersonCode = () => nextNumericCode("InvSalesPerson","SalesPersonCode",  "S",   4);

// ---------- COLLECTIONS (compat shim) ----------
export const COLLECTIONS = new Proxy({}, {
  get: (_, key) => resolveCollectionName(String(key)),
});
