// TOG.jsx — Firestore version
import React, { useCallback, useContext, useEffect, useMemo, useState } from "react";
import {
  ArrowRight, Check, ChevronDown, ClipboardList, Loader2, Package,
  Plus, RefreshCw, Search, Trash2, X,
} from "lucide-react";
import { doc, collection, serverTimestamp, increment } from "firebase/firestore";
import { db } from "../firebase.js";
import { COLLECTIONS, listCollection, runFirestoreTransaction } from "../lib/firestore";
import { AuthContext } from "../pos/SERVER/AuthContext.js";

const TOGS = COLLECTIONS?.TOG ?? "TOG";
const LOCATIONS = COLLECTIONS?.LOCATIONS ?? "Locations";
const PRODUCTS = COLLECTIONS?.PRODUCTS ?? "Products";
const PRODUCT_STOCK = COLLECTIONS?.PRODUCT_STOCK ?? "ProductStock";
const GRNS = COLLECTIONS?.GRN ?? "GRN";

const pick = (o, ...ks) => { for (const k of ks) if (o?.[k] != null) return o[k]; return ""; };
const toNum = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
const todayString = () => new Date().toISOString().slice(0, 10);
const getRows = (d) => Array.isArray(d) ? d : Array.isArray(d?.data) ? d.data : [];

const emptyForm = { togNo: "", togDate: todayString(), fromLocationID: "", toLocationID: "", referenceNo: "", remark: "" };

function TOG() {
  const { user } = useContext(AuthContext);
  const username = user?.username || user?.Username || "";

  const [form, setForm] = useState({ ...emptyForm });
  const [locations, setLocations] = useState([]);
  const [products, setProducts] = useState([]);
  const [items, setItems] = useState([]);
  const [loadingLocations, setLoadingLocations] = useState(false);
  const [loadingNumber, setLoadingNumber] = useState(false);
  const [loadingProducts, setLoadingProducts] = useState(false);
  const [saving, setSaving] = useState(false);
  const [loadingRecall, setLoadingRecall] = useState(false);
  const [productSearch, setProductSearch] = useState("");
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [showRecall, setShowRecall] = useState(false);
  const [recallType, setRecallType] = useState("GRN");
  const [recallSearch, setRecallSearch] = useState("");
  const [togList, setTogList] = useState([]);
  const [grnList, setGrnList] = useState([]);

  const clearMsgs = () => { setMessage(""); setError(""); };

  const loadTOGNumber = useCallback(async () => {
    setLoadingNumber(true);
    try {
      const rows = await listCollection(TOGS);
      let max = 0;
      rows.forEach((r) => {
        const m = String(pick(r, "TOGNo", "togNo") || "").match(/(\d+)$/);
        if (m) { const n = Number(m[1]); if (n > max) max = n; }
      });
      setForm((p) => ({ ...p, togNo: `TOG${String(max + 1).padStart(5, "0")}` }));
    } catch (err) {
      setError("Unable to generate TOG number.");
    } finally { setLoadingNumber(false); }
  }, []);

  const loadLocations = useCallback(async () => {
    setLoadingLocations(true);
    try {
      const rows = await listCollection(LOCATIONS, { where: [["IsDelete", "==", 0]] });
      setLocations(rows);
    } catch (err) { setError("Unable to load locations."); }
    finally { setLoadingLocations(false); }
  }, []);

  useEffect(() => { loadTOGNumber(); loadLocations(); }, [loadTOGNumber, loadLocations]);

  const locationOptions = useMemo(() => {
    const seen = new Set();
    return locations
      .map((r) => ({ id: pick(r, "LocationID", "locationID", "id"), name: pick(r, "LocationName", "locationName", "Name") }))
      .filter((r) => r.id !== "" && r.id != null && !seen.has(String(r.id)) && seen.add(String(r.id)));
  }, [locations]);

  const getLocationName = useCallback((id) => {
    if (id == null || id === "") return "";
    const row = locations.find((l) => String(pick(l, "LocationID", "locationID", "id")) === String(id));
    return row ? pick(row, "LocationName", "locationName", "Name") : "";
  }, [locations]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    clearMsgs();
    if (name === "fromLocationID") { setForm((p) => ({ ...p, fromLocationID: value, toLocationID: "" })); setItems([]); setProducts([]); setProductSearch(""); return; }
    if (name === "toLocationID") { setForm((p) => ({ ...p, toLocationID: value })); return; }
    setForm((p) => ({ ...p, [name]: value }));
  };

  const searchProducts = async () => {
    clearMsgs();
    const locationID = Number(form.fromLocationID);
    const searchText = productSearch.trim();
    if (!locationID) { setError("Please select From Location first."); return; }
    if (!searchText) { setProducts([]); return; }

    setLoadingProducts(true);
    try {
      const [prodRows, stockRows] = await Promise.all([
        listCollection(PRODUCTS, { where: [["IsDelete", "==", 0]] }),
        listCollection(PRODUCT_STOCK, { where: [["LocationID", "==", locationID], ["IsDelete", "==", 0]] }),
      ]);

      const stockMap = {};
      stockRows.forEach((s) => { const c = pick(s, "ProductCode", "productcode"); if (c) stockMap[c] = toNum(pick(s, "Stock", "CurrentStock")); });

      const q = searchText.toLowerCase();
      const filtered = prodRows.filter((p) => {
        const code = String(pick(p, "ProductCode", "productcode")).toLowerCase();
        const name = String(pick(p, "ProductName", "productname")).toLowerCase();
        return code.includes(q) || name.includes(q);
      }).slice(0, 30).map((p) => ({
        ...p,
        ProductCode: pick(p, "ProductCode", "productcode"),
        ProductName: pick(p, "ProductName", "productname"),
        Stock: stockMap[p.ProductCode] || 0,
        CostPrice: toNum(pick(p, "CostPrice", "costprice")),
        SellingPrice: toNum(pick(p, "SellingPrice", "sellingprice")),
      }));

      setProducts(filtered);
      if (filtered.length === 0) setMessage(`No products found for "${searchText}".`);
    } catch (err) { setProducts([]); setError(err.message || "Unable to search products."); }
    finally { setLoadingProducts(false); }
  };

  const addProduct = async (product) => {
    clearMsgs();
    if (!form.fromLocationID) { setError("Please select From Location."); return; }
    if (!form.toLocationID) { setError("Please select To Location."); return; }
    if (String(form.fromLocationID) === String(form.toLocationID)) { setError("From and To cannot match."); return; }
    if (items.some((i) => String(i.productCode).toLowerCase() === String(product.ProductCode).toLowerCase())) { setError(`${product.ProductCode} already added.`); return; }
    if (product.Stock <= 0) { setError(`${product.ProductName || product.ProductCode} has no stock here.`); return; }

    setItems((p) => [...p, {
      id: `${product.ProductCode}-${Date.now()}`,
      productCode: product.ProductCode, productName: product.ProductName,
      stock: product.Stock, costPrice: product.CostPrice, sellingPrice: product.SellingPrice, qty: 1,
    }]);
    setProducts([]); setProductSearch("");
    setMessage(`${product.ProductName || product.ProductCode} added.`);
  };

  const changeQty = (id, value) => {
    const qty = toNum(value);
    setItems((p) => p.map((i) => i.id === id ? { ...i, qty: qty > toNum(i.stock) ? toNum(i.stock) : qty } : i));
  };
  const removeItem = (id) => setItems((p) => p.filter((i) => i.id !== id));
  const totalQty = useMemo(() => items.reduce((s, i) => s + toNum(i.qty), 0), [items]);

  const validateTOG = () => {
    if (!form.togNo) return "TOG number required.";
    if (!form.togDate) return "TOG date required.";
    if (!form.fromLocationID) return "From Location required.";
    if (!form.toLocationID) return "To Location required.";
    if (String(form.fromLocationID) === String(form.toLocationID)) return "From/To must differ.";
    if (items.length === 0) return "Add at least one product.";
    for (const it of items) {
      if (!it.productCode) return "Product code missing.";
      if (toNum(it.qty) <= 0) return `${it.productCode}: qty > 0 required.`;
      if (toNum(it.qty) > toNum(it.stock)) return `${it.productCode}: qty exceeds stock.`;
    }
    return "";
  };

  const saveTOG = async () => {
    clearMsgs();
    const err = validateTOG();
    if (err) { setError(err); return; }

    setSaving(true);
    try {
      const fromID = Number(form.fromLocationID);
      const toID = Number(form.toLocationID);

      const result = await runFirestoreTransaction(async (tx) => {
        // 1. Read source stock docs
        const sourceStock = await listCollection(PRODUCT_STOCK, { where: [["LocationID", "==", fromID], ["IsDelete", "==", 0]] });
        const sourceMap = {};
        sourceStock.forEach((s) => { const c = pick(s, "ProductCode", "productcode"); if (c) sourceMap[c] = { id: s.id, stock: toNum(pick(s, "Stock", "CurrentStock")) }; });

        // 2. Read destination stock docs
        const destStock = await listCollection(PRODUCT_STOCK, { where: [["LocationID", "==", toID], ["IsDelete", "==", 0]] });
        const destMap = {};
        destStock.forEach((s) => { const c = pick(s, "ProductCode", "productcode"); if (c) destMap[c] = { id: s.id, stock: toNum(pick(s, "Stock", "CurrentStock")) }; });

        // 3. Validate + update
        for (const it of items) {
          const src = sourceMap[it.productCode];
          if (!src) throw new Error(`${it.productCode}: no stock doc at source.`);
          if (src.stock < toNum(it.qty)) throw new Error(`${it.productCode}: insufficient stock.`);

          tx.update(doc(db, PRODUCT_STOCK, src.id), { Stock: increment(-toNum(it.qty)), UpdatedAt: serverTimestamp() });

          if (destMap[it.productCode]) {
            tx.update(doc(db, PRODUCT_STOCK, destMap[it.productCode].id), { Stock: increment(toNum(it.qty)), UpdatedAt: serverTimestamp() });
          } else {
            // Create dest stock doc
            const newRef = doc(collection(db, PRODUCT_STOCK));
            tx.set(newRef, {
              ProductCode: it.productCode, ProductName: it.productName,
              LocationID: toID, Stock: toNum(it.qty),
              CreatedAt: serverTimestamp(), UpdatedAt: serverTimestamp(),
              IsDelete: 0,
            });
          }
        }

        // 4. Create TOG doc
        const togRef = doc(collection(db, TOGS));
        tx.set(togRef, {
          TOGNo: form.togNo, TOGDate: form.togDate,
          FromLocationID: fromID, ToLocationID: toID,
          ReferenceNo: form.referenceNo || "", Remark: form.remark || "",
          TotalQty: totalQty,
          items: items.map((it) => ({ ProductCode: it.productCode, ProductName: it.productName, Qty: toNum(it.qty), Stock: toNum(it.stock), CostPrice: toNum(it.costPrice), SellingPrice: toNum(it.sellingPrice) })),
          Status: "Completed",
          CreatedAt: serverTimestamp(), CreatedBy: username, IsDelete: 0,
        });

        return { togNo: form.togNo };
      });

      setMessage(`TOG ${result.togNo} saved successfully.`);
      setItems([]); setProducts([]); setProductSearch("");
      setForm((p) => ({ ...p, fromLocationID: "", toLocationID: "", referenceNo: "", remark: "" }));
      await loadTOGNumber();
    } catch (err) { setError(err.message || "Unable to save TOG."); }
    finally { setSaving(false); }
  };

  const newTOG = async () => { clearMsgs(); setForm({ ...emptyForm, togDate: todayString() }); setItems([]); setProducts([]); setProductSearch(""); await loadTOGNumber(); };

  const loadTOGList = async () => {
    try {
      const rows = await listCollection(TOGS, { where: [["IsDelete", "==", 0]] });
      setTogList(rows);
    } catch (err) { setError("Unable to load TOG list."); }
  };

  const loadGRNList = async () => {
    try {
      const rows = await listCollection(GRNS, { where: [["IsDelete", "==", 0]] });
      setGrnList(rows);
    } catch (err) { setError("Unable to load GRN list."); }
  };

  const openRecall = async (type) => {
    clearMsgs();
    setRecallType(type); setRecallSearch(""); setShowRecall(true); setLoadingRecall(true);
    try { if (type === "GRN") await loadGRNList(); else await loadTOGList(); }
    finally { setLoadingRecall(false); }
  };

  const recallTOG = async (row) => {
    clearMsgs();
    const togNo = pick(row, "TOGNo", "togNo");
    if (!togNo) { setError("Invalid TOG number."); return; }
    setLoadingRecall(true);
    try {
      const all = await listCollection(TOGS, { where: [["TOGNo", "==", togNo]] });
      const data = all[0];
      if (!data) throw new Error("TOG not found.");
      setForm({
        togNo: pick(data, "TOGNo"), togDate: String(pick(data, "TOGDate") || todayString()).substring(0, 10),
        fromLocationID: pick(data, "FromLocationID"), toLocationID: pick(data, "ToLocationID"),
        referenceNo: pick(data, "ReferenceNo"), remark: pick(data, "Remark"),
      });
      const items = (data.items || []).map((it, i) => ({
        id: `rec-${i}`, productCode: it.ProductCode, productName: it.ProductName,
        stock: toNum(it.Stock), costPrice: toNum(it.CostPrice), sellingPrice: toNum(it.SellingPrice), qty: toNum(it.Qty),
      }));
      setItems(items); setProducts([]); setProductSearch(""); setShowRecall(false);
      setMessage(`TOG ${togNo} recalled.`);
    } catch (err) { setError(err.message || "Unable to recall TOG."); }
    finally { setLoadingRecall(false); }
  };

  const recallGRN = async (row) => {
    clearMsgs();
    const grnNo = pick(row, "GRNNo", "grnNo");
    if (!grnNo) { setError("Invalid GRN number."); return; }
    setLoadingRecall(true);
    try {
      const all = await listCollection(GRNS, { where: [["GRNNo", "==", grnNo]] });
      const data = all[0];
      if (!data) throw new Error("GRN not found.");

      const grnLoc = pick(data, "LocationID", "location");
      const fromLoc = form.fromLocationID || grnLoc;
      setForm((p) => ({ ...p, fromLocationID: p.fromLocationID || grnLoc, referenceNo: grnNo, remark: p.remark || `Recalled from GRN ${grnNo}` }));

      // Load source stock
      const stockRows = fromLoc ? await listCollection(PRODUCT_STOCK, { where: [["LocationID", "==", Number(fromLoc)], ["IsDelete", "==", 0]] }) : [];
      const stockMap = {};
      stockRows.forEach((s) => { const c = pick(s, "ProductCode", "productcode"); if (c) stockMap[c] = toNum(pick(s, "Stock", "CurrentStock")); });

      const mapped = (data.items || []).map((it, i) => {
        const code = pick(it, "ProductCode", "productcode");
        const stock = stockMap[code] || 0;
        const grnQty = toNum(it.Qty);
        const qty = stock > 0 ? Math.min(grnQty > 0 ? grnQty : 1, stock) : 0;
        return {
          id: `grn-${i}`, productCode: code, productName: pick(it, "ProductName", "productname"),
          stock, costPrice: toNum(it.CostPrice), sellingPrice: toNum(it.SellingPrice), qty,
        };
      }).filter((it) => it.productCode);

      setItems(mapped); setProducts([]); setProductSearch(""); setShowRecall(false);
      setMessage(mapped.length === 0 ? `No usable products in GRN ${grnNo}.` : `GRN ${grnNo} recalled. ${mapped.length} products loaded.`);
    } catch (err) { setError(err.message || "Unable to recall GRN."); }
    finally { setLoadingRecall(false); }
  };

  const filteredRecallRows = useMemo(() => {
    const src = recallType === "GRN" ? grnList : togList;
    const q = recallSearch.trim().toLowerCase();
    if (!q) return src;
    return src.filter((r) => {
      const text = [pick(r, "GRNNo", "grnNo"), pick(r, "TOGNo", "togNo"), pick(r, "ReferenceNo"), pick(r, "SupplierName")].filter(Boolean).join(" ").toLowerCase();
      return text.includes(q);
    });
  }, [recallType, recallSearch, grnList, togList]);

  return (
    <div className="min-h-screen bg-slate-100 p-4 md:p-6">
      <div className="mx-auto max-w-7xl">
        <div className="mb-5 flex flex-col gap-4 rounded-xl bg-white p-5 shadow-sm lg:flex-row lg:items-center lg:justify-between">
          <div className="flex items-center gap-3">
            <div className="rounded-xl bg-indigo-600 p-3 text-white"><Package size={24} /></div>
            <div>
              <h1 className="text-2xl font-bold text-slate-800">Transfer Outgoing</h1>
              <p className="text-sm text-slate-500">Transfer stock from one location to another</p>
            </div>
          </div>
          <div className="flex flex-wrap gap-2">
            <button type="button" onClick={() => openRecall("GRN")}
              className="flex items-center gap-2 rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50">
              <ClipboardList size={17} /> Recall GRN
            </button>
            <button type="button" onClick={() => openRecall("TOG")}
              className="flex items-center gap-2 rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50">
              <RefreshCw size={17} /> Recall TOG
            </button>
            <button type="button" onClick={newTOG}
              className="flex items-center gap-2 rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50">
              <RefreshCw size={17} /> New
            </button>
            <button type="button" onClick={saveTOG} disabled={saving || loadingNumber}
              className="flex items-center gap-2 rounded-lg bg-indigo-600 px-5 py-2 text-sm font-bold text-white hover:bg-indigo-700 disabled:opacity-50">
              {saving ? <Loader2 size={17} className="animate-spin" /> : <Check size={17} />} {saving ? "Saving..." : "Save TOG"}
            </button>
          </div>
        </div>

        {message && <div className="mb-4 flex items-center justify-between rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-medium text-emerald-700"><span>{message}</span><button onClick={() => setMessage("")}><X size={17} /></button></div>}
        {error && <div className="mb-4 flex items-center justify-between rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700"><span>{error}</span><button onClick={() => setError("")}><X size={17} /></button></div>}

        <div className="mb-5 rounded-xl bg-white p-5 shadow-sm">
          <div className="mb-4 flex items-center gap-2"><ClipboardList size={19} className="text-indigo-600" /><h2 className="font-bold text-slate-800">Transfer Details</h2></div>
          <div className="grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-4">
            <div>
              <label className="mb-1 block text-xs font-semibold text-slate-600">TOG Number</label>
              <div className="relative">
                <input value={form.togNo} readOnly className="w-full rounded-lg border border-slate-300 bg-slate-100 px-3 py-2 text-sm font-bold text-slate-700" />
                {loadingNumber && <Loader2 size={16} className="absolute right-3 top-1/2 -translate-y-1/2 animate-spin text-indigo-600" />}
              </div>
            </div>
            <div>
              <label className="mb-1 block text-xs font-semibold text-slate-600">TOG Date *</label>
              <input type="date" name="togDate" value={form.togDate} onChange={handleChange}
                className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100" />
            </div>
            <div>
              <label className="mb-1 block text-xs font-semibold text-slate-600">From Location *</label>
              <select name="fromLocationID" value={form.fromLocationID || ""} onChange={handleChange} disabled={loadingLocations || locationOptions.length === 0}
                className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm outline-none disabled:bg-slate-100">
                <option value="">{loadingLocations ? "Loading..." : locationOptions.length === 0 ? "No locations" : "Select From Location"}</option>
                {locationOptions.map((l) => <option key={String(l.id)} value={String(l.id)}>{l.name || `Location ${l.id}`}</option>)}
              </select>
            </div>
            <div>
              <label className="mb-1 block text-xs font-semibold text-slate-600">To Location *</label>
              <select name="toLocationID" value={form.toLocationID || ""} onChange={handleChange} disabled={loadingLocations || locationOptions.length === 0}
                className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm outline-none disabled:bg-slate-100">
                <option value="">{loadingLocations ? "Loading..." : "Select To Location"}</option>
                {locationOptions.map((l) => {
                  const same = form.fromLocationID && String(l.id) === String(form.fromLocationID);
                  return <option key={String(l.id)} value={String(l.id)} disabled={same}>{l.name || `Location ${l.id}`}{same ? " (From)" : ""}</option>;
                })}
              </select>
            </div>
          </div>
          <div className="mt-4 grid grid-cols-1 gap-4 md:grid-cols-2">
            <div>
              <label className="mb-1 block text-xs font-semibold text-slate-600">Reference No</label>
              <input name="referenceNo" value={form.referenceNo} onChange={handleChange} placeholder="Optional reference"
                className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100" />
            </div>
            <div>
              <label className="mb-1 block text-xs font-semibold text-slate-600">Remark</label>
              <input name="remark" value={form.remark} onChange={handleChange} placeholder="Optional remark"
                className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100" />
            </div>
          </div>
        </div>

        <div className="mb-5 rounded-xl bg-white p-5 shadow-sm">
          <div className="mb-4 flex flex-col gap-2 md:flex-row md:items-center md:justify-between">
            <div className="flex items-center gap-2"><Search size={19} className="text-indigo-600" /><h2 className="font-bold text-slate-800">Search Product</h2></div>
            {form.fromLocationID && <div className="rounded-full bg-indigo-50 px-3 py-1 text-xs font-bold text-indigo-700">Stock Location: {getLocationName(form.fromLocationID) || form.fromLocationID}</div>}
          </div>
          <div className="flex flex-col gap-2 md:flex-row">
            <div className="relative flex-1">
              <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <input value={productSearch} onChange={(e) => setProductSearch(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") searchProducts(); }}
                disabled={!form.fromLocationID}
                placeholder={form.fromLocationID ? "Search product..." : "Select From Location first..."}
                className="w-full rounded-lg border border-slate-300 py-2.5 pl-10 pr-3 text-sm outline-none disabled:bg-slate-100" />
            </div>
            <button type="button" onClick={searchProducts} disabled={loadingProducts || !form.fromLocationID || !productSearch.trim()}
              className="flex items-center justify-center gap-2 rounded-lg bg-indigo-600 px-6 py-2.5 text-sm font-bold text-white hover:bg-indigo-700 disabled:opacity-50">
              {loadingProducts ? <Loader2 size={17} className="animate-spin" /> : <Search size={17} />} Search
            </button>
          </div>
          {products.length > 0 && (
            <div className="mt-4 overflow-hidden rounded-lg border border-slate-200">
              <div className="max-h-80 overflow-y-auto">
                {products.map((p, i) => (
                  <div key={`${p.ProductCode}-${i}`} className="flex flex-col gap-3 border-b border-slate-100 p-4 last:border-0 hover:bg-slate-50 md:flex-row md:items-center md:justify-between">
                    <div className="min-w-0">
                      <div className="font-bold text-slate-800">{p.ProductName || "Unnamed"}</div>
                      <div className="mt-1 flex flex-wrap gap-2">
                        <span className="rounded bg-slate-100 px-2 py-1 text-xs font-semibold text-slate-600">{p.ProductCode}</span>
                        <span className={`rounded px-2 py-1 text-xs font-bold ${p.Stock > 0 ? "bg-emerald-50 text-emerald-700" : "bg-red-50 text-red-700"}`}>Stock: {p.Stock}</span>
                      </div>
                    </div>
                    <button type="button" onClick={() => addProduct(p)} disabled={p.Stock <= 0}
                      className="flex items-center justify-center gap-2 rounded-lg bg-emerald-600 px-5 py-2 text-sm font-bold text-white hover:bg-emerald-700 disabled:bg-slate-300">
                      <Plus size={17} /> {p.Stock > 0 ? "Add" : "No Stock"}
                    </button>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="overflow-hidden rounded-xl bg-white shadow-sm">
          <div className="flex flex-col gap-3 border-b border-slate-200 p-5 md:flex-row md:items-center md:justify-between">
            <div><h2 className="font-bold text-slate-800">Transfer Items</h2><p className="text-xs text-slate-500">{items.length} product(s)</p></div>
            <div className="rounded-lg bg-indigo-50 px-4 py-2 text-sm font-bold text-indigo-700">Total Qty: <span className="ml-1 text-lg">{totalQty}</span></div>
          </div>
          <div className="overflow-x-auto">
            <table className="min-w-full text-sm">
              <thead className="bg-slate-50">
                <tr>
                  <th className="px-4 py-3 text-left text-xs font-bold uppercase text-slate-500">#</th>
                  <th className="px-4 py-3 text-left text-xs font-bold uppercase text-slate-500">Product Code</th>
                  <th className="px-4 py-3 text-left text-xs font-bold uppercase text-slate-500">Product Name</th>
                  <th className="px-4 py-3 text-right text-xs font-bold uppercase text-slate-500">Stock</th>
                  <th className="px-4 py-3 text-right text-xs font-bold uppercase text-slate-500">Qty</th>
                  <th className="px-4 py-3 text-center text-xs font-bold uppercase text-slate-500">Action</th>
                </tr>
              </thead>
              <tbody>
                {items.length === 0 ? (
                  <tr><td colSpan="6" className="px-4 py-16 text-center">
                    <Package size={42} className="mx-auto mb-3 text-slate-300" />
                    <div className="font-semibold text-slate-500">No products added</div>
                    <div className="mt-1 text-xs text-slate-400">Search a product and click Add.</div>
                  </td></tr>
                ) : items.map((item, i) => (
                  <tr key={item.id} className="border-t border-slate-100">
                    <td className="px-4 py-3 text-slate-500">{i + 1}</td>
                    <td className="px-4 py-3 font-bold text-slate-700">{item.productCode}</td>
                    <td className="px-4 py-3 font-medium text-slate-800">{item.productName}</td>
                    <td className="px-4 py-3 text-right font-bold text-slate-600">{item.stock}</td>
                    <td className="px-4 py-3 text-right">
                      <input type="number" min="0" max={item.stock} step="0.001" value={item.qty} onChange={(e) => changeQty(item.id, e.target.value)}
                        className="w-28 rounded-lg border border-slate-300 px-3 py-2 text-right font-bold outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100" />
                    </td>
                    <td className="px-4 py-3 text-center">
                      <button type="button" onClick={() => removeItem(item.id)} className="rounded-lg p-2 text-red-500 hover:bg-red-50"><Trash2 size={18} /></button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        <div className="mt-5 flex flex-col gap-3 rounded-xl bg-white p-4 shadow-sm md:flex-row md:items-center md:justify-between">
          <div className="text-sm text-slate-500">
            <span className="font-bold text-slate-700">{getLocationName(form.fromLocationID) || "From Location"}</span>
            <ArrowRight size={16} className="mx-2 inline" />
            <span className="font-bold text-slate-700">{getLocationName(form.toLocationID) || "To Location"}</span>
          </div>
          <button type="button" onClick={saveTOG} disabled={saving || loadingNumber}
            className="flex items-center justify-center gap-2 rounded-lg bg-indigo-600 px-7 py-3 font-bold text-white hover:bg-indigo-700 disabled:opacity-50">
            {saving ? <Loader2 size={18} className="animate-spin" /> : <Check size={18} />} {saving ? "Saving TOG..." : `Save TOG ${form.togNo || ""}`}
          </button>
        </div>
      </div>

      {showRecall && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="flex max-h-[90vh] w-full max-w-5xl flex-col overflow-hidden rounded-xl bg-white shadow-2xl">
            <div className="flex items-center justify-between border-b border-slate-200 p-5">
              <div><h2 className="text-xl font-bold text-slate-800">Recall {recallType}</h2><p className="text-xs text-slate-500">Select a document to load into TOG.</p></div>
              <button type="button" onClick={() => setShowRecall(false)} className="rounded-lg p-2 text-slate-500 hover:bg-slate-100"><X size={20} /></button>
            </div>
            <div className="flex gap-2 border-b border-slate-200 p-4">
              <button type="button" onClick={() => openRecall("GRN")} className={`rounded-lg px-4 py-2 text-sm font-bold ${recallType === "GRN" ? "bg-indigo-600 text-white" : "bg-slate-100 text-slate-600"}`}>GRN</button>
              <button type="button" onClick={() => openRecall("TOG")} className={`rounded-lg px-4 py-2 text-sm font-bold ${recallType === "TOG" ? "bg-indigo-600 text-white" : "bg-slate-100 text-slate-600"}`}>TOG</button>
            </div>
            <div className="border-b border-slate-200 p-4">
              <div className="relative">
                <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                <input value={recallSearch} onChange={(e) => setRecallSearch(e.target.value)} placeholder={`Search ${recallType} number...`}
                  className="w-full rounded-lg border border-slate-300 py-2.5 pl-10 pr-3 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100" />
              </div>
            </div>
            <div className="flex-1 overflow-y-auto">
              {loadingRecall ? <div className="flex items-center justify-center py-16"><Loader2 size={32} className="animate-spin text-indigo-600" /></div>
                : filteredRecallRows.length === 0 ? <div className="py-16 text-center text-slate-400">No {recallType} documents found.</div>
                : <div className="divide-y divide-slate-100">
                    {filteredRecallRows.map((row, index) => {
                      const documentNo = recallType === "GRN" ? pick(row, "GRNNo", "grnNo") : pick(row, "TOGNo", "togNo");
                      const date = pick(row, "TOGDate", "GRNDate", "DocumentDate");
                      return (
                        <div key={row.id || `${documentNo}-${index}`} className="flex flex-col gap-3 p-4 hover:bg-slate-50 md:flex-row md:items-center md:justify-between">
                          <div>
                            <div className="font-bold text-slate-800">{documentNo || "Unknown"}</div>
                            {date && <div className="mt-1 text-xs text-slate-500">{String(date).substring(0, 10)}</div>}
                          </div>
                          <button type="button" onClick={() => recallType === "GRN" ? recallGRN(row) : recallTOG(row)} disabled={loadingRecall}
                            className="flex items-center justify-center gap-2 rounded-lg bg-indigo-600 px-5 py-2 text-sm font-bold text-white hover:bg-indigo-700 disabled:opacity-50">
                            {loadingRecall ? <Loader2 size={17} className="animate-spin" /> : <ChevronDown size={17} />} Recall
                          </button>
                        </div>
                      );
                    })}
                  </div>}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default TOG;