/* ============================================================
   BOOLEAN FIELDS
============================================================ */
const BOOLEAN_FIELDS = [
  "IsActive",
  "ShowLogo", "ShowCustomer", "ShowCustomerAddress", "ShowCustomerPhone",
  "ShowCustomerEmail", "ShowTax", "ShowDiscount", "ShowPaymentMethod",
  "ShowCashier", "ShowDateTime", "ShowPromotions",
  "InvoiceHeaderBold", "InvoiceHeaderItalic",
  "CustomerBold", "CustomerItalic",
  "ItemBold", "ItemItalic",
  "PromotionBold", "PromotionItalic",
  "TotalBold", "TotalItalic",
  "FooterBold", "FooterItalic",
  "AllowInvoiceEditing", "AllowInvoiceNumberEditing", "AllowInvoiceDateEditing",
  "AllowCustomerEditing", "AllowItemPriceEditing", "AllowInvoiceDiscountEditing",
  "AutoPrintReceipt", "OpenCashDrawer",
  "AllowNegativeStock", "AllowPriceEditing", "AllowDiscount", "AllowReturns",
  "AllowTransportCharge", "AllowManualDiscount",
];

/* ============================================================
   HELPERS
============================================================ */
const normalizeBoolean = (value, fallback = false) => {
  if (value === undefined || value === null) return fallback;
  if (typeof value === "boolean") return value;
  if (value === 1 || value === "1" || value === "true") return true;
  return false;
};

const alignClass = (value) => {
  switch (value) {
    case "center": return "text-center";
    case "right":  return "text-right";
    default:       return "text-left";
  }
};

const styleClass = (bold, italic) =>
  [bold ? "font-bold" : "font-normal", italic ? "italic" : "not-italic"].join(" ");

const getPaperWidth = (paperSize) => {
  switch (paperSize) {
    case "58mm": return "w-[220px]";
    case "80mm": return "w-[300px]";
    case "A5":   return "w-[500px]";
    case "A4":   return "w-[650px]";
    default:     return "w-[300px]";
  }
};

/* ============================================================
   SECTION CARD
============================================================ */
function SectionCard({ icon: Icon, title, description, children }) {
  return (
    <section className="rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-200 px-5 py-4">
        <div className="flex items-start gap-3">
          <div className="rounded-lg bg-slate-100 p-2">
            <Icon size={20} className="text-slate-700" />
          </div>
          <div>
            <h2 className="font-semibold text-slate-800">{title}</h2>
            {description && (
              <p className="mt-1 text-sm text-slate-500">{description}</p>
            )}
          </div>
        </div>
      </div>
      <div className="p-5">{children}</div>
    </section>
  );
}

/* ============================================================
   FIELDS
============================================================ */
function InputField({
  label, name, value, onChange, type = "text",
  placeholder = "", min, max, step, disabled = false,
}) {
  return (
    <div>
      <label className="mb-1.5 block text-sm font-medium text-slate-700">{label}</label>
      <input
        type={type} name={name} value={value ?? ""} onChange={onChange}
        placeholder={placeholder} min={min} max={max} step={step} disabled={disabled}
        className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100 disabled:bg-slate-100"
      />
    </div>
  );
}

function SelectField({ label, name, value, onChange, options }) {
  return (
    <div>
      <label className="mb-1.5 block text-sm font-medium text-slate-700">{label}</label>
      <select
        name={name} value={value ?? ""} onChange={onChange}
        className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
      >
        {options.map((option) => (
          <option key={option.value} value={option.value}>{option.label}</option>
        ))}
      </select>
    </div>
  );
}

function TextAreaField({ label, name, value, onChange, rows = 3, placeholder = "" }) {
  return (
    <div>
      <label className="mb-1.5 block text-sm font-medium text-slate-700">{label}</label>
      <textarea
        name={name} value={value ?? ""} onChange={onChange} rows={rows} placeholder={placeholder}
        className="w-full resize-y rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
      />
    </div>
  );
}

function ToggleField({ label, description, name, checked, onChange }) {
  return (
    <label className="flex cursor-pointer items-start justify-between gap-4 rounded-lg border border-slate-200 bg-slate-50 p-4">
      <div>
        <div className="font-medium text-slate-800">{label}</div>
        {description && <div className="mt-1 text-xs text-slate-500">{description}</div>}
      </div>
      <input
        type="checkbox" name={name} checked={Boolean(checked)} onChange={onChange}
        className="mt-1 h-5 w-5 cursor-pointer rounded border-slate-300 text-blue-600 focus:ring-blue-500"
      />
    </label>
  );
}

function StyleControls({ title, boldName, italicName, boldValue, italicValue, onChange }) {
  return (
    <div className="rounded-lg border border-slate-200 bg-slate-50 p-4">
      <p className="mb-3 text-sm font-semibold text-slate-700">{title}</p>
      <div className="flex flex-wrap gap-3">
        <label className="flex cursor-pointer items-center gap-2 rounded-lg border border-slate-200 bg-white px-4 py-2.5">
          <input type="checkbox" name={boldName} checked={Boolean(boldValue)} onChange={onChange}
            className="h-4 w-4 rounded border-slate-300 text-blue-600" />
          <Bold size={16} /><span className="text-sm">Bold</span>
        </label>
        <label className="flex cursor-pointer items-center gap-2 rounded-lg border border-slate-200 bg-white px-4 py-2.5">
          <input type="checkbox" name={italicName} checked={Boolean(italicValue)} onChange={onChange}
            className="h-4 w-4 rounded border-slate-300 text-blue-600" />
          <Italic size={16} /><span className="text-sm">Italic</span>
        </label>
      </div>
    </div>
  );
}

function AlignmentButtons({ label, name, value, onChange }) {
  const options = [
    { value: "left",   label: "Left",   icon: AlignLeft   },
    { value: "center", label: "Center", icon: AlignCenter },
    { value: "right",  label: "Right",  icon: AlignRight  },
  ];
  return (
    <div>
      <label className="mb-2 block text-sm font-medium text-slate-700">{label}</label>
      <div className="flex gap-2">
        {options.map((option) => {
          const Icon = option.icon;
          const active = value === option.value;
          return (
            <label key={option.value}
              className={`flex cursor-pointer items-center gap-2 rounded-lg border px-4 py-2.5 text-sm transition ${
                active
                  ? "border-blue-500 bg-blue-50 text-blue-700"
                  : "border-slate-200 bg-white text-slate-600 hover:bg-slate-50"
              }`}>
              <input type="radio" name={name} value={option.value} checked={active}
                onChange={onChange} className="sr-only" />
              <Icon size={16} />
              {option.label}
            </label>
          );
        })}
      </div>
    </div>
  );
}

