/**
 * Reads product-level discount from a Product Master row.
 *   FixedDiscountPercentage → discount percent
 *   FixedDiscount           → discount price (amount)
 *   MaximumDiscount         → cap
 * Priority: percentage wins when both > 0.
 */
const readProductDiscount = (product) => {
    const empty = { type: "NONE", value: 0, max: 0, pct: 0, amt: 0 };
    if (!product) return empty;

    const pct = Number(product.FixedDiscountPercentage ?? 0);
    const amt = Number(product.FixedDiscount ?? 0);
    const max = Number(product.MaximumDiscount ?? 0);

    if (Number.isFinite(pct) && pct > 0) {
        return { type: "PERCENT", value: pct, max: max > 0 ? max : 0, pct, amt };
    }
    if (Number.isFinite(amt) && amt > 0) {
        return { type: "AMOUNT", value: amt, max: max > 0 ? max : 0, pct, amt };
    }
    return { ...empty, pct, amt };
};


/**
 * Given a list price and a product row, compute the actual per-unit discount
 * and the resulting net unit price.
 */
const computeLineDiscount = (listPrice, product) => {
    const gross = Number(listPrice || 0);
    const d = readProductDiscount(product);

    let unitDiscount = 0;
    if (d.type === "PERCENT" && d.value > 0) {
        unitDiscount = (gross * d.value) / 100;
    } else if (d.type === "AMOUNT" && d.value > 0) {
        unitDiscount = d.value;
    }

    if (d.max > 0 && unitDiscount > d.max) {
        unitDiscount = d.max;
    }
    if (unitDiscount > gross) unitDiscount = gross;

    return {
        grossPrice: Number(gross.toFixed(2)),
        unitDiscount: Number(unitDiscount.toFixed(2)),
        netUnitPrice: Number((gross - unitDiscount).toFixed(2)),
        discountType: d.type,
        discountValue: d.value,
        discountMax: d.max,
        fixedDiscount: d.amt,
        fixedDiscountPercentage: d.pct
    };
};


