// Supplierpayment.jsx — Firestore version
import React, { useEffect, useMemo, useState } from "react";
import { doc, collection, writeBatch, serverTimestamp, increment } from "firebase/firestore";
import { db } from "../firebase.js";
import { COLLECTIONS, listCollection, createDoc } from "../lib/firestore";

const SUPPLIERS = COLLECTIONS?.SUPPLIERS ?? "Suppliers";
const GRNS = COLLECTIONS?.GRN ?? "GRN";
const PAYMENTS = COLLECTIONS?.SUPPLIER_PAYMENTS ?? "SupplierPayments";

const PAYMENT_METHODS = ["Cash", "Bank Transfer", "Cheque", "Card", "Other"];

const pick = (o, ...ks) => { for (const k of ks) if (o?.[k] != null) return o[k]; return ""; };
const toNum = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };

const initialForm = {
  paymentDate: new Date().toISOString().split("T")[0],
  paymentAmount: "", paymentMethod: "Cash", referenceNo: "", remark: "",
};

const SupplierPayment = () => {
  const [suppliers, setSuppliers] = useState([]);
  const [grns, setGrns] = useState([]);
  const [payments, setPayments] = useState([]);
  const [grnDetails, setGrnDetails] = useState([]);
  const [supplierCode, setSupplierCode] = useState("");
  const [selectedGRN, setSelectedGRN] = useState(null);
  const [form, setForm] = useState(initialForm);
  const [supplierSearch, setSupplierSearch] = useState("");
  const [grnSearch, setGrnSearch] = useState("");
  const [loadingSuppliers, setLoadingSuppliers] = useState(false);
  const [loadingGRNs, setLoadingGRNs] = useState(false);
  const [loadingDetails, setLoadingDetails] = useState(false);
  const [loadingHistory, setLoadingHistory] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const fmt = (v) => Number(v || 0).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const fmtQty = (v) => Number(v || 0).toLocaleString("en-US", { minimumFractionDigits: 3, maximumFractionDigits: 3 });
  const fmtDate = (v) => {
    if (!v) return "-";
    const d = v.toDate ? v.toDate() : v.seconds ? new Date(v.seconds * 1000) : new Date(v);
    return Number.isNaN(d.getTime()) ? String(v) : d.toLocaleDateString("en-GB");
  };
  const clearMsgs = () => { setError(""); setSuccess(""); };

  useEffect(() => { loadSuppliers(); }, []);

  const loadSuppliers = async () => {
    try {
      setLoadingSuppliers(true); setError("");
      const rows = await listCollection(SUPPLIERS, { where: [["IsDelete", "==", 0]] });
      setSuppliers(rows.map((r) => ({
        SupplierCode: pick(r, "SupplierCode", "suppliercode"),
        SupplierName: pick(r, "SupplierName", "suppliername"),
      })).filter((s) => s.SupplierCode));
    } catch (err) { setError(err.message || "Failed to load suppliers"); }
    finally { setLoadingSuppliers(false); }
  };

  const loadGRNs = async (code) => {
    if (!code) { setGrns([]); return; }
    try {
      setLoadingGRNs(true); setError("");
      const [grnRows, payRows] = await Promise.all([
        listCollection(GRNS, { where: [["SupplierCode", "==", code], ["IsDelete", "==", 0]] }),
        listCollection(PAYMENTS, { where: [["SupplierCode", "==", code], ["IsDelete", "==", 0]] }),
      ]);

      const paidByGRN = {};
      payRows.forEach((p) => {
        const grnId = p.GRNID || p.GrnID;
        if (grnId) paidByGRN[grnId] = (paidByGRN[grnId] || 0) + toNum(p.PaymentAmount);
      });

      const mapped = grnRows.map((g) => {
        const items = Array.isArray(g.items) ? g.items : [];
        const totalNet = items.reduce((s, it) => {
          const qty = toNum(it.Qty);
          const cost = toNum(it.CostPrice);
          const disc = toNum(it.FixedDiscountPercentage);
          const gross = qty * cost;
          return s + gross - gross * disc / 100;
        }, 0);
        const totalPaid = toNum(g.TotalPaid) || paidByGRN[g.id] || 0;
        const balance = Math.max(totalNet - totalPaid, 0);

        return {
          GRNID: g.id,
          GRNNo: pick(g, "GRNNo", "grnno"),
          GRNDate: pick(g, "GRNDate", "grndate"),
          PONo: pick(g, "PONo", "pono"),
          ReferenceNo: pick(g, "ReferenceNo", "referenceno"),
          LocationID: pick(g, "LocationID", "location"),
          PaymentType: pick(g, "PaymentType", "paymenttype"),
          ItemCount: items.length,
          TotalQty: items.reduce((s, it) => s + toNum(it.Qty), 0),
          TotalNet: totalNet, TotalPaid: totalPaid, BalanceAmount: balance,
        };
      }).filter((g) => g.BalanceAmount > 0);

      setGrns(mapped);
    } catch (err) { setError(err.message || "Failed to load GRNs"); setGrns([]); }
    finally { setLoadingGRNs(false); }
  };

  const loadPaymentHistory = async (code) => {
    if (!code) { setPayments([]); return; }
    try {
      setLoadingHistory(true);
      const rows = await listCollection(PAYMENTS, { where: [["SupplierCode", "==", code], ["IsDelete", "==", 0]] });
      setPayments(rows.map((p) => ({
        PaymentID: p.id,
        GRNNo: pick(p, "GRNNo", "grnNo"),
        PaymentDate: pick(p, "PaymentDate", "paymentDate"),
        PaymentAmount: toNum(p.PaymentAmount),
        PaymentMethod: pick(p, "PaymentMethod", "paymentMethod"),
        ReferenceNo: pick(p, "ReferenceNo", "referenceNo"),
        Remark: pick(p, "Remark", "remark"),
        Username: pick(p, "CreatedBy", "username"),
        CreatedDate: pick(p, "CreatedAt", "createdAt"),
      })));
    } catch (err) { setError(err.message || "Failed to load payment history"); setPayments([]); }
    finally { setLoadingHistory(false); }
  };

  const loadGRNDetails = async (grnId) => {
    if (!grnId) { setGrnDetails([]); return; }
    try {
      setLoadingDetails(true);
      const rows = await listCollection(GRNS);
      const grn = rows.find((r) => r.id === grnId);
      if (!grn) { setGrnDetails([]); return; }
      const items = Array.isArray(grn.items) ? grn.items : [];
      setGrnDetails(items.map((it, i) => ({
        GRNDetailID: `${grnId}-${i}`,
        ProductCode: it.ProductCode, ProductName: it.ProductName,
        Qty: toNum(it.Qty), CostPrice: toNum(it.CostPrice),
        FixedDiscountPercentage: toNum(it.FixedDiscountPercentage),
        GrossAmount: toNum(it.Qty) * toNum(it.CostPrice),
        DiscountAmount: toNum(it.Qty) * toNum(it.CostPrice) * toNum(it.FixedDiscountPercentage) / 100,
        NetAmount: toNum(it.Qty) * toNum(it.CostPrice) * (1 - toNum(it.FixedDiscountPercentage) / 100),
      })));
    } catch (err) { setError(err.message || "Failed to load GRN details"); setGrnDetails([]); }
    finally { setLoadingDetails(false); }
  };

  const handleSupplierChange = async (e) => {
    const code = e.target.value;
    clearMsgs();
    setSupplierCode(code); setSelectedGRN(null); setGrnDetails([]); setGrnSearch(""); setForm(initialForm);
    if (!code) { setGrns([]); setPayments([]); return; }
    await Promise.all([loadGRNs(code), loadPaymentHistory(code)]);
  };

  const handleSelectGRN = async (grn) => {
    clearMsgs();
    setSelectedGRN(grn);
    setForm((p) => ({ ...p, paymentAmount: Number(grn.BalanceAmount || 0).toFixed(2) }));
    await loadGRNDetails(grn.GRNID);
  };

  const handleFormChange = (e) => {
    const { name, value } = e.target;
    setForm((p) => ({ ...p, [name]: value }));
    clearMsgs();
  };

  const handlePayFullBalance = () => {
    if (!selectedGRN) return;
    setForm((p) => ({ ...p, paymentAmount: Number(selectedGRN.BalanceAmount || 0).toFixed(2) }));
    clearMsgs();
  };

  const clearSelectedGRN = () => { setSelectedGRN(null); setGrnDetails([]); setForm(initialForm); clearMsgs(); };

  const handleSubmit = async (e) => {
    e.preventDefault();
    clearMsgs();
    if (!supplierCode) { setError("Please select a supplier."); return; }
    if (!selectedGRN) { setError("Please select a GRN."); return; }
    if (!form.paymentDate) { setError("Please select a payment date."); return; }

    const amount = Number(form.paymentAmount || 0);
    const balance = Number(selectedGRN.BalanceAmount || 0);
    if (!Number.isFinite(amount) || amount <= 0) { setError("Amount must be greater than zero."); return; }
    if (balance <= 0) { setError("No outstanding balance."); return; }
    if (amount > balance + 0.001) { setError(`Amount exceeds balance of ${fmt(balance)}.`); return; }
    if (!form.paymentMethod) { setError("Please select a payment method."); return; }
    if ((form.paymentMethod === "Cheque" || form.paymentMethod === "Bank Transfer") && !form.referenceNo.trim()) {
      setError(`Reference number required for ${form.paymentMethod}.`); return;
    }

    try {
      setSaving(true);
      const batch = writeBatch(db);
      const payRef = doc(collection(db, PAYMENTS));
      batch.set(payRef, {
        GRNID: selectedGRN.GRNID, GRNNo: selectedGRN.GRNNo,
        SupplierCode: supplierCode,
        PaymentDate: form.paymentDate,
        PaymentAmount: Number(amount.toFixed(2)),
        PaymentMethod: form.paymentMethod,
        ReferenceNo: form.referenceNo.trim() || null,
        Remark: form.remark.trim() || null,
        LocationID: selectedGRN.LocationID,
        CreatedAt: serverTimestamp(),
        CreatedBy: "admin",
        IsDelete: 0,
      });
      batch.update(doc(db, GRNS, selectedGRN.GRNID), {
        TotalPaid: increment(Number(amount.toFixed(2))),
        UpdatedAt: serverTimestamp(),
      });
      await batch.commit();

      setSuccess(`Payment saved. ID: ${payRef.id}`);
      setForm({ ...initialForm, paymentDate: new Date().toISOString().split("T")[0] });
      setSelectedGRN(null); setGrnDetails([]);
      await loadGRNs(supplierCode);
      await loadPaymentHistory(supplierCode);
    } catch (err) { setError(err.message || "Failed to save payment."); }
    finally { setSaving(false); }
  };

  const filteredSuppliers = useMemo(() => {
    const s = supplierSearch.trim().toLowerCase();
    if (!s) return suppliers;
    return suppliers.filter((x) =>
      String(x.SupplierCode).toLowerCase().includes(s) ||
      String(x.SupplierName).toLowerCase().includes(s)
    );
  }, [suppliers, supplierSearch]);

  const filteredGRNs = useMemo(() => {
    const s = grnSearch.trim().toLowerCase();
    if (!s) return grns;
    return grns.filter((g) =>
      String(g.GRNNo).toLowerCase().includes(s) ||
      String(g.PONo).toLowerCase().includes(s) ||
      String(g.ReferenceNo).toLowerCase().includes(s)
    );
  }, [grns, grnSearch]);

  const supplierTotals = useMemo(() => grns.reduce((t, g) => ({
    totalNet: t.totalNet + g.TotalNet, totalPaid: t.totalPaid + g.TotalPaid, balance: t.balance + g.BalanceAmount,
  }), { totalNet: 0, totalPaid: 0, balance: 0 }), [grns]);

  const detailTotals = useMemo(() => grnDetails.reduce((t, it) => ({
    qty: t.qty + it.Qty, gross: t.gross + it.GrossAmount, discount: t.discount + it.DiscountAmount, net: t.net + it.NetAmount,
  }), { qty: 0, gross: 0, discount: 0, net: 0 }), [grnDetails]);

  const paymentPreview = useMemo(() => {
    if (!selectedGRN) return { payment: 0, remaining: 0 };
    const p = Number(form.paymentAmount || 0);
    return { payment: p, remaining: Math.max(Number(selectedGRN.BalanceAmount || 0) - p, 0) };
  }, [selectedGRN, form.paymentAmount]);

  const cardStyle = { background: "#fff", borderRadius: "10px", padding: "20px", marginBottom: "20px", boxShadow: "0 1px 4px rgba(0,0,0,0.08)" };
  const sectionTitle = { margin: "0 0 15px 0", fontSize: "18px" };
  const labelStyle = { display: "block", fontSize: "13px", fontWeight: 600, marginBottom: "6px", color: "#374151" };
  const inputStyle = { width: "100%", boxSizing: "border-box", padding: "10px 12px", border: "1px solid #d1d5db", borderRadius: "6px", background: "#fff", fontSize: "14px", outline: "none" };
  const tableStyle = { width: "100%", borderCollapse: "collapse", fontSize: "13px" };
  const btn = (bg) => ({ background: bg, color: "#fff", border: "none", borderRadius: "6px", padding: "10px 16px", cursor: "pointer", fontSize: "13px", fontWeight: 600 });

  return (
    <div style={{ width: "100%", padding: "24px", boxSizing: "border-box", fontFamily: "Arial, sans-serif", background: "#f5f6f8", minHeight: "100vh" }}>
      <div style={{ background: "#fff", borderRadius: "10px", padding: "20px 24px", marginBottom: "20px", boxShadow: "0 1px 4px rgba(0,0,0,0.08)" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: "15px", flexWrap: "wrap" }}>
          <div>
            <h2 style={{ margin: 0, fontSize: "24px" }}>Supplier Payment</h2>
            <div style={{ marginTop: "5px", color: "#666", fontSize: "14px" }}>Manage supplier payments against GRNs</div>
          </div>
          <button type="button" onClick={() => { loadSuppliers(); if (supplierCode) { loadGRNs(supplierCode); loadPaymentHistory(supplierCode); } }}
            disabled={loadingSuppliers || loadingGRNs || loadingHistory} style={btn("#374151")}>Refresh</button>
        </div>
      </div>

      {error && <div style={{ background: "#fee2e2", border: "1px solid #fecaca", color: "#991b1b", padding: "12px 15px", borderRadius: "8px", marginBottom: "15px" }}>{error}</div>}
      {success && <div style={{ background: "#dcfce7", border: "1px solid #bbf7d0", color: "#166534", padding: "12px 15px", borderRadius: "8px", marginBottom: "15px" }}>{success}</div>}

      <div style={cardStyle}>
        <h3 style={sectionTitle}>Supplier</h3>
        <div style={{ display: "grid", gridTemplateColumns: "minmax(200px, 1fr) minmax(200px, 1fr)", gap: "15px" }}>
          <div>
            <label style={labelStyle}>Search Supplier</label>
            <input type="text" value={supplierSearch} onChange={(e) => setSupplierSearch(e.target.value)} placeholder="Search code or name..." style={inputStyle} />
          </div>
          <div>
            <label style={labelStyle}>Supplier</label>
            <select value={supplierCode} onChange={handleSupplierChange} style={inputStyle} disabled={loadingSuppliers}>
              <option value="">{loadingSuppliers ? "Loading..." : "Select Supplier"}</option>
              {filteredSuppliers.map((s) => (<option key={s.SupplierCode} value={s.SupplierCode}>{s.SupplierCode} - {s.SupplierName}</option>))}
            </select>
          </div>
        </div>
      </div>

      {supplierCode && (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(3, minmax(150px, 1fr))", gap: "15px", marginBottom: "20px" }}>
          <SummaryCard title="Outstanding GRN Total" value={fmt(supplierTotals.totalNet)} />
          <SummaryCard title="Already Paid" value={fmt(supplierTotals.totalPaid)} />
          <SummaryCard title="Supplier Outstanding" value={fmt(supplierTotals.balance)} />
        </div>
      )}

      {supplierCode && (
        <div style={cardStyle}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: "15px", marginBottom: "15px", flexWrap: "wrap" }}>
            <h3 style={{ ...sectionTitle, marginBottom: 0 }}>Outstanding GRNs</h3>
            <input type="text" value={grnSearch} onChange={(e) => setGrnSearch(e.target.value)} placeholder="Search GRN / PO / reference..."
              style={{ ...inputStyle, width: "300px", maxWidth: "100%" }} />
          </div>
          {loadingGRNs ? <LoadingMsg text="Loading GRNs..." /> : (
            <div style={{ overflowX: "auto" }}>
              <table style={tableStyle}>
                <thead>
                  <tr>
                    <th>GRN No</th><th>Date</th><th>PO No</th><th>Reference</th><th>Items</th><th>Qty</th>
                    <th>Net Total</th><th>Paid</th><th>Balance</th><th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredGRNs.length === 0 ? (
                    <tr><td colSpan="10" style={{ textAlign: "center", padding: "30px", color: "#777" }}>No outstanding GRNs found.</td></tr>
                  ) : filteredGRNs.map((grn) => (
                    <tr key={grn.GRNID} style={{ background: selectedGRN?.GRNID === grn.GRNID ? "#eff6ff" : "#fff" }}>
                      <td><strong>{grn.GRNNo}</strong></td>
                      <td>{fmtDate(grn.GRNDate)}</td>
                      <td>{grn.PONo || "-"}</td>
                      <td>{grn.ReferenceNo || "-"}</td>
                      <td style={{ textAlign: "right" }}>{grn.ItemCount ?? "-"}</td>
                      <td style={{ textAlign: "right" }}>{fmtQty(grn.TotalQty)}</td>
                      <td style={{ textAlign: "right" }}>{fmt(grn.TotalNet)}</td>
                      <td style={{ textAlign: "right" }}>{fmt(grn.TotalPaid)}</td>
                      <td style={{ textAlign: "right", fontWeight: "bold" }}>{fmt(grn.BalanceAmount)}</td>
                      <td><button type="button" onClick={() => handleSelectGRN(grn)} style={btn("#2563eb")}>Select</button></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {selectedGRN && (
        <div style={cardStyle}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "15px", gap: "15px", flexWrap: "wrap" }}>
            <h3 style={{ ...sectionTitle, marginBottom: 0 }}>GRN Details - {selectedGRN.GRNNo}</h3>
            <button type="button" onClick={clearSelectedGRN} style={btn("#6b7280")}>Close</button>
          </div>

          <div style={{ display: "grid", gridTemplateColumns: "repeat(5, minmax(120px, 1fr))", gap: "12px", marginBottom: "20px" }}>
            <InfoBox label="GRN No" value={selectedGRN.GRNNo} />
            <InfoBox label="GRN Date" value={fmtDate(selectedGRN.GRNDate)} />
            <InfoBox label="PO No" value={selectedGRN.PONo || "-"} />
            <InfoBox label="Reference" value={selectedGRN.ReferenceNo || "-"} />
            <InfoBox label="Payment Type" value={selectedGRN.PaymentType || "-"} />
          </div>

          <div style={{ display: "grid", gridTemplateColumns: "repeat(5, minmax(140px, 1fr))", gap: "12px", marginBottom: "20px" }}>
            <AmountBox label="Gross" value={selectedGRN.TotalNet + supplierTotals.totalPaid} />
            <AmountBox label="Discount" value={0} />
            <AmountBox label="Net Total" value={selectedGRN.TotalNet} />
            <AmountBox label="Paid" value={selectedGRN.TotalPaid} />
            <AmountBox label="Balance" value={selectedGRN.BalanceAmount} strong />
          </div>

          <h4 style={{ margin: "10px 0" }}>GRN Items</h4>
          {loadingDetails ? <LoadingMsg text="Loading GRN items..." /> : (
            <div style={{ overflowX: "auto", marginBottom: "25px" }}>
              <table style={tableStyle}>
                <thead><tr><th>#</th><th>Product Code</th><th>Product Name</th><th>Qty</th><th>Cost Price</th><th>Discount %</th><th>Gross</th><th>Discount</th><th>Net Amount</th></tr></thead>
                <tbody>
                  {grnDetails.length === 0 ? <tr><td colSpan="9" style={{ textAlign: "center", padding: "25px" }}>No items.</td></tr> :
                    grnDetails.map((it, i) => (
                      <tr key={it.GRNDetailID}>
                        <td>{i + 1}</td>
                        <td>{it.ProductCode}</td>
                        <td>{it.ProductName}</td>
                        <td style={{ textAlign: "right" }}>{fmtQty(it.Qty)}</td>
                        <td style={{ textAlign: "right" }}>{fmt(it.CostPrice)}</td>
                        <td style={{ textAlign: "right" }}>{Number(it.FixedDiscountPercentage).toFixed(2)}%</td>
                        <td style={{ textAlign: "right" }}>{fmt(it.GrossAmount)}</td>
                        <td style={{ textAlign: "right" }}>{fmt(it.DiscountAmount)}</td>
                        <td style={{ textAlign: "right", fontWeight: "bold" }}>{fmt(it.NetAmount)}</td>
                      </tr>
                    ))}
                </tbody>
                {grnDetails.length > 0 && (
                  <tfoot><tr>
                    <th colSpan="3">Total</th>
                    <th style={{ textAlign: "right" }}>{fmtQty(detailTotals.qty)}</th>
                    <th></th><th></th>
                    <th style={{ textAlign: "right" }}>{fmt(detailTotals.gross)}</th>
                    <th style={{ textAlign: "right" }}>{fmt(detailTotals.discount)}</th>
                    <th style={{ textAlign: "right" }}>{fmt(detailTotals.net)}</th>
                  </tr></tfoot>
                )}
              </table>
            </div>
          )}

          <div style={{ borderTop: "1px solid #e5e7eb", paddingTop: "20px" }}>
            <h4 style={{ marginTop: 0 }}>Make Payment</h4>
            <form onSubmit={handleSubmit}>
              <div style={{ display: "grid", gridTemplateColumns: "repeat(2, minmax(200px, 1fr))", gap: "15px" }}>
                <div>
                  <label style={labelStyle}>Payment Date *</label>
                  <input type="date" name="paymentDate" value={form.paymentDate} onChange={handleFormChange} required style={inputStyle} />
                </div>
                <div>
                  <label style={labelStyle}>Payment Amount *</label>
                  <div style={{ display: "flex", gap: "8px" }}>
                    <input type="number" name="paymentAmount" value={form.paymentAmount} onChange={handleFormChange} min="0.01" max={Number(selectedGRN.BalanceAmount || 0)} step="0.01" required style={{ ...inputStyle, flex: 1 }} />
                    <button type="button" onClick={handlePayFullBalance} style={btn("#059669")}>Full</button>
                  </div>
                  <div style={{ fontSize: "12px", marginTop: "5px", color: "#666" }}>Maximum: {fmt(selectedGRN.BalanceAmount)}</div>
                </div>
                <div>
                  <label style={labelStyle}>Payment Method *</label>
                  <select name="paymentMethod" value={form.paymentMethod} onChange={handleFormChange} required style={inputStyle}>
                    {PAYMENT_METHODS.map((m) => <option key={m} value={m}>{m}</option>)}
                  </select>
                </div>
                <div>
                  <label style={labelStyle}>Reference No{(form.paymentMethod === "Cheque" || form.paymentMethod === "Bank Transfer") && " *"}</label>
                  <input type="text" name="referenceNo" value={form.referenceNo} onChange={handleFormChange} maxLength="100"
                    placeholder={form.paymentMethod === "Cheque" ? "Cheque number" : form.paymentMethod === "Bank Transfer" ? "Bank reference" : "Optional"} style={inputStyle} />
                </div>
              </div>
              <div style={{ marginTop: "15px" }}>
                <label style={labelStyle}>Remark</label>
                <textarea name="remark" value={form.remark} onChange={handleFormChange} maxLength="500" rows="3" style={{ ...inputStyle, resize: "vertical" }} />
              </div>
              <div style={{ marginTop: "20px", padding: "15px", borderRadius: "8px", background: "#f8fafc", border: "1px solid #e2e8f0", display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: "15px" }}>
                <AmountBox label="Current Balance" value={selectedGRN.BalanceAmount} />
                <AmountBox label="Payment" value={paymentPreview.payment} />
                <AmountBox label="Balance After" value={paymentPreview.remaining} strong />
              </div>
              <div style={{ display: "flex", justifyContent: "flex-end", gap: "10px", marginTop: "20px" }}>
                <button type="button" onClick={clearSelectedGRN} disabled={saving} style={btn("#6b7280")}>Cancel</button>
                <button type="submit" disabled={saving || loadingDetails} style={{ ...btn("#2563eb"), minWidth: "150px" }}>{saving ? "Saving..." : "Save Payment"}</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {supplierCode && (
        <div style={cardStyle}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "15px" }}>
            <h3 style={{ ...sectionTitle, marginBottom: 0 }}>Payment History</h3>
            {loadingHistory && <span style={{ fontSize: "13px", color: "#666" }}>Loading...</span>}
          </div>
          <div style={{ overflowX: "auto" }}>
            <table style={tableStyle}>
              <thead><tr><th>Payment ID</th><th>GRN No</th><th>Date</th><th>Amount</th><th>Method</th><th>Reference</th><th>Remark</th><th>User</th><th>Created</th></tr></thead>
              <tbody>
                {payments.length === 0 ? <tr><td colSpan="9" style={{ textAlign: "center", padding: "30px", color: "#777" }}>No history.</td></tr> :
                  payments.map((p) => (
                    <tr key={p.PaymentID}>
                      <td>{p.PaymentID}</td>
                      <td>{p.GRNNo}</td>
                      <td>{fmtDate(p.PaymentDate)}</td>
                      <td style={{ textAlign: "right", fontWeight: "bold" }}>{fmt(p.PaymentAmount)}</td>
                      <td>{p.PaymentMethod}</td>
                      <td>{p.ReferenceNo || "-"}</td>
                      <td>{p.Remark || "-"}</td>
                      <td>{p.Username || "-"}</td>
                      <td>{fmtDate(p.CreatedDate)}</td>
                    </tr>
                  ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

const SummaryCard = ({ title, value }) => (
  <div style={{ background: "#fff", borderRadius: "10px", padding: "18px", boxShadow: "0 1px 4px rgba(0,0,0,0.08)" }}>
    <div style={{ fontSize: "13px", color: "#6b7280", marginBottom: "8px" }}>{title}</div>
    <div style={{ fontSize: "20px", fontWeight: 700 }}>{value}</div>
  </div>
);
const InfoBox = ({ label, value }) => (
  <div style={{ background: "#f8fafc", border: "1px solid #e5e7eb", borderRadius: "7px", padding: "12px" }}>
    <div style={{ fontSize: "11px", color: "#6b7280", marginBottom: "5px", textTransform: "uppercase" }}>{label}</div>
    <div style={{ fontWeight: 600, wordBreak: "break-word" }}>{value}</div>
  </div>
);
const AmountBox = ({ label, value, strong }) => (
  <div style={{ background: strong ? "#eff6ff" : "#f8fafc", border: "1px solid #e5e7eb", borderRadius: "7px", padding: "12px" }}>
    <div style={{ fontSize: "12px", color: "#6b7280", marginBottom: "5px" }}>{label}</div>
    <div style={{ fontSize: "17px", fontWeight: strong ? 700 : 600 }}>{Number(value || 0).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</div>
  </div>
);
const LoadingMsg = ({ text }) => <div style={{ padding: "30px", textAlign: "center", color: "#666" }}>{text}</div>;

export default SupplierPayment;