// ExpenseManagement.jsx
// ============================================================
// Expense Management — Firestore version
// ------------------------------------------------------------
// Record, view and delete expense transactions.
//
// Firestore collections used:
//   - Expenses             (flat expense list for reporting)
//   - Accounts             (source + destination + category source)
//   - AccountTransactions  (ledger legs: debit source, credit dest)
//
// Each expense creates FOUR writes atomically:
//   1. Expenses doc
//   2. AccountTransactions (Debit on source)
//   3. AccountTransactions (Credit on destination)
//   4. Accounts.StoredBalance updates (source −, dest +)
//
// Summary + cash-on-hand are computed client-side from the
// loaded data (matches the original REST endpoints).
// ============================================================

import React, {
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from "react";

import {
  doc,
  collection,
  serverTimestamp,
} from "firebase/firestore";

import {
  Plus,
  X,
  Filter,
  Calendar,
  Search,
  ChevronDown,
  Trash2,
  Pencil,
  BarChart3,
  MessageSquare,
  History,
  Wallet,
  IndianRupee,
} from "lucide-react";

import {
  COLLECTIONS,
  listCollection,
  runFirestoreTransaction,
  softDeleteDoc,
} from "../lib/firestore.js";

import { db } from "../firebase.js";
import { AuthContext } from "../pos/SERVER/AuthContext.js";

/* ======================================================
   CONSTANTS
====================================================== */

const EXPENSES = "Expenses";

/* ======================================================
   HELPERS
====================================================== */

const pad = (n) => String(n).padStart(2, "0");

const getToday = () => {
  const d = new Date();
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
};

const getFirstDayOfMonth = () => {
  const d = new Date();
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-01`;
};

const getLastMonthDates = () => {
  const d = new Date();
  const first = new Date(d.getFullYear(), d.getMonth() - 1, 1);
  const last = new Date(d.getFullYear(), d.getMonth(), 0);
  return {
    from: `${first.getFullYear()}-${pad(first.getMonth() + 1)}-01`,
    to: `${last.getFullYear()}-${pad(last.getMonth() + 1)}-${pad(
      last.getDate()
    )}`,
  };
};

const formatMoney = (value) =>
  Number(value || 0).toLocaleString("en-LK", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });

const toDate = (value) => {
  if (!value) return null;
  if (typeof value?.toDate === "function") {
    const d = value.toDate();
    return Number.isNaN(d.getTime()) ? null : d;
  }
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d;
};

const toDateOnly = (value) => {
  const d = toDate(value);
  if (!d) return null;
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
};

const formatDate = (value) => {
  const d = toDate(value);
  return d ? d.toLocaleDateString("en-GB") : "-";
};

const normalizeAccount = (raw) => ({
  AccountID: raw.id,
  AccountName: raw.AccountName ?? raw.name ?? "Unnamed Account",
  AccountType: raw.AccountType ?? raw.type ?? "",
  DetailType: raw.DetailType ?? raw.detailType ?? "",
  AccountNumber: raw.AccountNumber ?? "",
  StoredBalance: Number(raw.StoredBalance ?? raw.balance ?? 0),
  HasStoredBalance:
    raw.StoredBalance !== undefined ||
    raw.storedBalance !== undefined ||
    raw.balance !== undefined,
});

const normalizeExpense = (raw) => {
  const rawDate = raw.ExpenseDate ?? raw.expenseDate ?? raw.TransactionDate ?? null;
  return {
    TransactionID: raw.id,
    ExpenseDate: rawDate,
    dateOnly: toDateOnly(rawDate),
    FromAccountID: raw.FromAccountID ?? raw.fromAccountID ?? "",
    FromAccountName: raw.FromAccountName ?? "",
    ToAccountID: raw.ToAccountID ?? raw.toAccountID ?? "",
    ToAccountName: raw.ToAccountName ?? raw.AccountName ?? "",
    AccountName: raw.AccountName ?? raw.ToAccountName ?? "",
    Category: raw.Category ?? raw.category ?? "",
    Description: raw.Description ?? raw.description ?? "",
    ReferenceNo: raw.ReferenceNo ?? raw.referenceNo ?? "",
    Amount: Number(raw.Amount ?? raw.amount ?? 0),
  };
};

/* ======================================================
   COMPONENT
====================================================== */

const ExpenseManagement = () => {
  const { user } = useContext(AuthContext);
  const username = user?.username || "admin";

  /* ---------- DATA ---------- */
  const [expenses, setExpenses] = useState([]);
  const [accounts, setAccounts] = useState([]);

  /* ---------- LOADING ---------- */
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);

  /* ---------- MODAL ---------- */
  const [showModal, setShowModal] = useState(false);

  /* ---------- CATEGORY DROPDOWN ---------- */
  const [categoryOpen, setCategoryOpen] = useState(false);
  const [categorySearch, setCategorySearch] = useState("");

  /* ---------- FILTERS ---------- */
  const [filterAccount, setFilterAccount] = useState("");
  const [paymentMethod, setPaymentMethod] = useState("All");
  const [fromDate, setFromDate] = useState(getFirstDayOfMonth());
  const [toDate, setToDate] = useState(getToday());
  const [search, setSearch] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("");

  /* ---------- FORM ---------- */
  const [form, setForm] = useState({
    expenseDate: getToday(),
    fromAccountID: "",
    toAccountID: "",
    category: "",
    description: "",
    referenceNo: "",
    amount: "",
  });

  /* ---------- MESSAGES ---------- */
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  /* ======================================================
     LOAD ACCOUNTS
  ====================================================== */

  const loadAccounts = useCallback(async () => {
    try {
      const rows = await listCollection(COLLECTIONS.ACCOUNTS, {
        where: [["IsDelete", "==", 0]],
      });

      setAccounts(
        rows
          .map(normalizeAccount)
          .filter((a) => a.AccountID)
          .sort((a, b) => a.AccountName.localeCompare(b.AccountName))
      );
    } catch (err) {
      console.error("LOAD ACCOUNTS ERROR:", err);
      setAccounts([]);
      setError(err.message || "Unable to load accounts");
    }
  }, []);

  /* ======================================================
     LOAD EXPENSES
     ------------------------------------------------------
     Fetches ALL expenses, then filters client-side by
     date range, account, category, and search. This avoids
     needing composite indexes on (ExpenseDate, AccountID).
  ====================================================== */

  const loadExpenses = useCallback(async () => {
    try {
      setLoading(true);

      const rows = await listCollection(EXPENSES, {
        where: [["IsDelete", "==", 0]],
      });

      const normalized = rows
        .map(normalizeExpense)
        .filter((e) => e.TransactionID)
        .sort((a, b) => (b.dateOnly || "") < (a.dateOnly || "") ? -1 : 1);

      setExpenses(normalized);
    } catch (err) {
      console.error("LOAD EXPENSES ERROR:", err);
      setExpenses([]);
      setError(err.message || "Unable to load expenses");
    } finally {
      setLoading(false);
    }
  }, []);

  /* ---------- INITIAL LOAD ---------- */

  useEffect(() => {
    loadAccounts();
    loadExpenses();
  }, [loadAccounts, loadExpenses]);

  /* ======================================================
     FILTERED EXPENSES (client-side)
  ====================================================== */

  const filteredExpenses = useMemo(() => {
    const fromStr = fromDate || "";
    const toStr = toDate || "";
    const q = search.trim().toLowerCase();

    return expenses.filter((e) => {
      if (fromStr && e.dateOnly && e.dateOnly < fromStr) return false;
      if (toStr && e.dateOnly && e.dateOnly > toStr) return false;

      if (
        filterAccount &&
        String(e.FromAccountID) !== String(filterAccount) &&
        String(e.ToAccountID) !== String(filterAccount)
      ) {
        return false;
      }

      if (
        categoryFilter &&
        String(e.Category).toLowerCase() !== categoryFilter.toLowerCase()
      ) {
        return false;
      }

      if (q) {
        const hay =
          `${e.Description} ${e.Category} ${e.ReferenceNo} ${e.AccountName}`.toLowerCase();
        if (!hay.includes(q)) return false;
      }

      return true;
    });
  }, [expenses, fromDate, toDate, filterAccount, categoryFilter, search]);

  /* ======================================================
     SUMMARY (client-side)
  ====================================================== */

  const totalExpenses = useMemo(
    () => filteredExpenses.reduce((s, e) => s + Number(e.Amount || 0), 0),
    [filteredExpenses]
  );

  const expenseCount = filteredExpenses.length;

  /* ======================================================
     CASH ON HAND
     ------------------------------------------------------
     Sum of StoredBalance on cash-type accounts (or filtered
     account). Mirrors the original /api/expenses/cash-on-hand
     semantics.
  ====================================================== */

  const cashOnHand = useMemo(() => {
    if (filterAccount) {
      const a = accounts.find(
        (x) => String(x.AccountID) === String(filterAccount)
      );
      return a ? Number(a.StoredBalance || 0) : 0;
    }

    const cashAccounts = accounts.filter(
      (a) =>
        String(a.AccountType).toLowerCase() === "cash" ||
        String(a.AccountType).toLowerCase() === "cash_on_hand" ||
        String(a.AccountType).toLowerCase() === "cash on hand"
    );

    const source = cashAccounts.length > 0 ? cashAccounts : accounts;

    return source.reduce((s, a) => s + Number(a.StoredBalance || 0), 0);
  }, [accounts, filterAccount]);

  /* ======================================================
     CATEGORY OPTIONS (from accounts)
  ====================================================== */

  const categoryOptions = useMemo(() => {
    const unique = new Map();

    accounts.forEach((a) => {
      const name = String(a.AccountName || "").trim();
      if (name) unique.set(name, name);
    });

    return Array.from(unique.values()).sort((a, b) => a.localeCompare(b));
  }, [accounts]);

  const filteredCategories = categoryOptions.filter((c) =>
    c.toLowerCase().includes(categorySearch.toLowerCase().trim())
  );

  /* ======================================================
     QUICK DATE FILTERS
  ====================================================== */

  const selectThisMonth = () => {
    setFromDate(getFirstDayOfMonth());
    setToDate(getToday());
  };

  const selectLastMonth = () => {
    const { from, to } = getLastMonthDates();
    setFromDate(from);
    setToDate(to);
  };

  const selectAllTime = () => {
    setFromDate("");
    setToDate("");
  };

  /* ======================================================
     MODAL
  ====================================================== */

  const openAddExpense = () => {
    setError("");
    setSuccess("");
    setForm({
      expenseDate: getToday(),
      fromAccountID: "",
      toAccountID: "",
      category: "",
      description: "",
      referenceNo: "",
      amount: "",
    });
    setCategoryOpen(false);
    setCategorySearch("");
    setShowModal(true);
  };

  const closeModal = () => {
    if (saving) return;
    setShowModal(false);
    setCategoryOpen(false);
  };

  const updateForm = (field, value) => {
    setForm((prev) => ({ ...prev, [field]: value }));
  };

  const selectCategory = (category) => {
    updateForm("category", category);
    setCategoryOpen(false);
    setCategorySearch("");
  };

  /* ======================================================
     SAVE EXPENSE
     ------------------------------------------------------
     Atomic transaction:
       1. Read both accounts
       2. Update StoredBalance (from −, to +)
       3. Create Expenses record
       4. Create Debit AccountTransaction
       5. Create Credit AccountTransaction
  ====================================================== */

  const saveExpense = async (event) => {
    event.preventDefault();
    setError("");
    setSuccess("");

    if (!form.fromAccountID) return setError("Please select a from account.");
    if (!form.toAccountID) return setError("Please select a to account.");

    if (String(form.fromAccountID) === String(form.toAccountID)) {
      return setError("From and To accounts cannot be the same.");
    }

    const amount = Number(form.amount);
    if (!Number.isFinite(amount) || amount <= 0) {
      return setError("Please enter a valid expense amount.");
    }

    if (!form.expenseDate) return setError("Expense date is required.");

    try {
      setSaving(true);

      await runFirestoreTransaction(async (tx) => {
        const fromRef = doc(db, COLLECTIONS.ACCOUNTS, form.fromAccountID);
        const toRef = doc(db, COLLECTIONS.ACCOUNTS, form.toAccountID);

        const fromSnap = await tx.get(fromRef);
        const toSnap = await tx.get(toRef);

        if (!fromSnap.exists()) throw new Error("Source account not found.");
        if (!toSnap.exists()) throw new Error("Destination account not found.");

        const from = fromSnap.data();
        const to = toSnap.data();
        const fromBalance = Number(from.StoredBalance || 0);

        if (fromBalance < amount) {
          throw new Error(
            `Insufficient funds in ${from.AccountName || "source"} (Rs.${formatMoney(fromBalance)}).`
          );
        }

        /* ---- 1. Update balances ---- */

        tx.update(fromRef, {
          StoredBalance: fromBalance - amount,
          ModifiedAt: serverTimestamp(),
          ModifiedBy: username,
        });

        tx.update(toRef, {
          StoredBalance: Number(to.StoredBalance || 0) + amount,
          ModifiedAt: serverTimestamp(),
          ModifiedBy: username,
        });

        /* ---- 2. Expense record ---- */

        const expenseRef = doc(collection(db, EXPENSES));
        tx.set(expenseRef, {
          ExpenseDate: form.expenseDate,
          FromAccountID: form.fromAccountID,
          FromAccountName: from.AccountName || "",
          ToAccountID: form.toAccountID,
          ToAccountName: to.AccountName || "",
          AccountName: from.AccountName || "", // legacy display field
          Category: form.category || to.AccountName || "Uncategorized",
          Description: form.description.trim() || "",
          ReferenceNo: form.referenceNo.trim() || "",
          Amount: amount,
          CreatedAt: serverTimestamp(),
          CreatedBy: username,
          ModifiedAt: serverTimestamp(),
          ModifiedBy: username,
          IsDelete: 0,
        });

        /* ---- 3. Debit leg (source) ---- */

        const debitRef = doc(collection(db, COLLECTIONS.ACCOUNT_TRANSACTIONS));
        tx.set(debitRef, {
          AccountID: form.fromAccountID,
          AccountName: from.AccountName || "",
          AccountType: from.AccountType || "",
          DetailType: from.DetailType || "",
          TransactionDate: form.expenseDate,
          TransactionType: "Expense",
          Description:
            form.description.trim() ||
            `Expense to ${to.AccountName || "expense account"}`,
          ReferenceNo: form.referenceNo.trim() || "",
          Debit: amount,
          Credit: 0,
          Category: form.category || "",
          IsReconciled: 0,
          IsDelete: 0,
          CreatedAt: serverTimestamp(),
          CreatedBy: username,
        });

        /* ---- 4. Credit leg (destination) ---- */

        const creditRef = doc(collection(db, COLLECTIONS.ACCOUNT_TRANSACTIONS));
        tx.set(creditRef, {
          AccountID: form.toAccountID,
          AccountName: to.AccountName || "",
          AccountType: to.AccountType || "",
          DetailType: to.DetailType || "",
          TransactionDate: form.expenseDate,
          TransactionType: "Expense",
          Description:
            form.description.trim() ||
            `Expense from ${from.AccountName || "cash account"}`,
          ReferenceNo: form.referenceNo.trim() || "",
          Debit: 0,
          Credit: amount,
          Category: form.category || "",
          IsReconciled: 0,
          IsDelete: 0,
          CreatedAt: serverTimestamp(),
          CreatedBy: username,
        });
      });

      setSuccess("Expense recorded successfully.");
      setShowModal(false);
      setForm({
        expenseDate: getToday(),
        fromAccountID: "",
        toAccountID: "",
        category: "",
        description: "",
        referenceNo: "",
        amount: "",
      });

      await Promise.all([loadExpenses(), loadAccounts()]);
    } catch (err) {
      console.error("SAVE EXPENSE ERROR:", err);
      setError(err.message || "Unable to save expense.");
    } finally {
      setSaving(false);
    }
  };

  /* ======================================================
     DELETE EXPENSE (soft)
     ------------------------------------------------------
     Reverses the ledger: credit source, debit destination.
     Also rewrites balances back to pre-expense values.
  ====================================================== */

  const deleteExpense = async (expense) => {
    if (!expense?.TransactionID) return;
    if (
      !window.confirm(
        `Delete this expense of Rs.${formatMoney(expense.Amount)}?`
      )
    ) {
      return;
    }

    try {
      setLoading(true);

      await runFirestoreTransaction(async (tx) => {
        const fromRef = doc(db, COLLECTIONS.ACCOUNTS, expense.FromAccountID);
        const toRef = doc(db, COLLECTIONS.ACCOUNTS, expense.ToAccountID);

        const fromSnap = await tx.get(fromRef);
        const toSnap = await tx.get(toRef);

        const amount = Number(expense.Amount || 0);

        /* ---- Reverse balances ---- */

        if (fromSnap.exists()) {
          const from = fromSnap.data();
          tx.update(fromRef, {
            StoredBalance: Number(from.StoredBalance || 0) + amount,
            ModifiedAt: serverTimestamp(),
            ModifiedBy: username,
          });
        }

        if (toSnap.exists()) {
          const to = toSnap.data();
          tx.update(toRef, {
            StoredBalance: Math.max(0, Number(to.StoredBalance || 0) - amount),
            ModifiedAt: serverTimestamp(),
            ModifiedBy: username,
          });
        }

        /* ---- Soft-delete expense ---- */

        const expenseRef = doc(db, EXPENSES, expense.TransactionID);
        tx.update(expenseRef, {
          IsDelete: 1,
          DeletedAt: serverTimestamp(),
          DeletedBy: username,
        });
      });

      setSuccess("Expense deleted successfully.");
      await Promise.all([loadExpenses(), loadAccounts()]);
    } catch (err) {
      console.error("DELETE EXPENSE ERROR:", err);
      setError(err.message || "Unable to delete expense.");
    } finally {
      setLoading(false);
    }
  };

  /* ======================================================
     CLEAR FILTERS
  ====================================================== */

  const clearFilters = () => {
    setFilterAccount("");
    setPaymentMethod("All");
    setCategoryFilter("");
    setSearch("");
    setFromDate(getFirstDayOfMonth());
    setToDate(getToday());
  };

  /* ======================================================
     RENDER
  ====================================================== */

  return (
    <div className="min-h-screen bg-white px-5 py-5 md:px-9">
      <div className="mx-auto max-w-[1220px]">
        {/* HEADER */}
        <div className="flex flex-col gap-4 md:flex-row md:items-start md:justify-between">
          <div>
            <h1 className="text-3xl font-bold text-slate-950">
              Expense Management
            </h1>
            <p className="mt-1 text-base text-slate-600">
              {fromDate && toDate
                ? `Showing: ${formatDate(fromDate)} - ${formatDate(toDate)}`
                : "Showing: All dates"}
            </p>
          </div>

          <button
            type="button"
            onClick={openAddExpense}
            className="flex items-center justify-center gap-2 rounded-xl bg-amber-500 px-5 py-3 font-semibold text-white shadow-sm hover:bg-amber-600"
          >
            <Plus size={18} />
            Add Expense
          </button>
        </div>

        {/* QUICK DATE FILTERS */}
        <div className="mt-6 flex flex-wrap gap-2">
          <button
            type="button"
            onClick={selectThisMonth}
            className="rounded-xl bg-amber-500 px-4 py-2.5 text-sm font-semibold text-white"
          >
            This Month
          </button>
          <button
            type="button"
            onClick={selectLastMonth}
            className="rounded-xl border border-slate-200 px-4 py-2.5 text-sm hover:bg-slate-50"
          >
            Last Month
          </button>
          <button
            type="button"
            onClick={selectAllTime}
            className="rounded-xl border border-slate-200 px-4 py-2.5 text-sm hover:bg-slate-50"
          >
            All Time
          </button>
        </div>

        {/* MESSAGES */}
        {success && (
          <div className="mt-5 rounded-xl border border-green-200 bg-green-50 px-4 py-3 text-sm text-green-700">
            {success}
          </div>
        )}
        {error && !showModal && (
          <div className="mt-5 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
            {error}
          </div>
        )}

        {/* SUMMARY CARDS */}
        <div className="mt-6 grid grid-cols-1 gap-4 md:grid-cols-2">
          <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
            <div className="flex items-start justify-between">
              <div>
                <p className="text-sm font-medium text-slate-700">
                  Filtered Expenses
                </p>
                <p className="mt-2 text-2xl font-bold text-slate-950">
                  Rs. {formatMoney(totalExpenses)}
                </p>
                <p className="mt-1 text-sm text-slate-500">
                  {expenseCount} expenses
                </p>
              </div>
              <div className="text-slate-500">
                <IndianRupee size={16} />
              </div>
            </div>
          </div>

          <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
            <div className="flex items-start justify-between">
              <div>
                <p className="text-sm font-medium text-slate-700">
                  Cash on Hand
                </p>
                <p className="mt-2 text-2xl font-bold text-slate-950">
                  Rs. {formatMoney(cashOnHand)}
                </p>
                <p className="mt-1 text-xs font-medium uppercase text-slate-500">
                  CASH ON HAND
                </p>
              </div>
              <Wallet size={17} className="text-slate-500" />
            </div>
          </div>
        </div>

        {/* EXPENSE HISTORY */}
        <div className="mt-6 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm md:p-6">
          <div className="flex flex-col gap-4 xl:flex-row xl:items-start xl:justify-between">
            <div>
              <h2 className="text-2xl font-bold text-slate-950">
                Expense History
              </h2>
              <p className="mt-1 text-sm text-slate-600">
                View and filter expense transactions
              </p>
            </div>

            <div className="flex flex-wrap gap-2">
              <button
                type="button"
                className="flex items-center gap-2 rounded-lg border border-slate-200 px-3 py-2 text-sm hover:bg-slate-50"
              >
                <Filter size={16} />
              </button>
              <button
                type="button"
                onClick={clearFilters}
                className="flex items-center gap-2 rounded-lg border border-slate-200 px-3 py-2 text-sm hover:bg-slate-50"
              >
                <X size={15} />
                Clear Filters
              </button>
              <button
                type="button"
                className="flex items-center gap-2 rounded-lg border border-slate-200 px-3 py-2 text-sm hover:bg-slate-50"
              >
                <BarChart3 size={16} />
                Category Wise
              </button>
              <button
                type="button"
                className="flex items-center gap-2 rounded-lg border border-slate-200 px-3 py-2 text-sm hover:bg-slate-50"
              >
                <Calendar size={16} />
                Date Wise
              </button>
              <button
                type="button"
                className="flex items-center gap-2 rounded-lg border border-slate-200 px-3 py-2 text-sm hover:bg-slate-50"
              >
                <MessageSquare size={16} />
                Test SMS
              </button>
              <button
                type="button"
                className="flex items-center gap-2 rounded-lg border border-slate-200 px-3 py-2 text-sm hover:bg-slate-50"
              >
                <History size={16} />
                Modifications
              </button>
            </div>
          </div>

          {/* SEARCH */}
          <div className="relative mt-5">
            <Search
              size={17}
              className="absolute left-3 top-3 text-slate-400"
            />
            <input
              type="text"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search description, category or reference..."
              className="w-full rounded-xl border border-slate-200 py-2.5 pl-10 pr-3 outline-none focus:border-amber-400"
            />
          </div>

          {/* FILTERS */}
          <div className="mt-4 grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">
            <div>
              <label className="mb-2 block text-sm font-medium">Account</label>
              <div className="relative">
                <select
                  value={filterAccount}
                  onChange={(e) => setFilterAccount(e.target.value)}
                  className="w-full appearance-none rounded-xl border border-slate-200 bg-white px-3 py-2.5 outline-none"
                >
                  <option value="">All accounts</option>
                  {accounts.map((a) => (
                    <option key={a.AccountID} value={a.AccountID}>
                      {a.AccountName}
                    </option>
                  ))}
                </select>
                <ChevronDown
                  size={17}
                  className="pointer-events-none absolute right-3 top-3.5 text-slate-400"
                />
              </div>
            </div>

            <div>
              <label className="mb-2 block text-sm font-medium">
                Payment Method
              </label>
              <select
                value={paymentMethod}
                onChange={(e) => setPaymentMethod(e.target.value)}
                className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 outline-none"
              >
                <option value="All">All methods</option>
                <option value="Cash">Cash</option>
                <option value="Bank">Bank</option>
                <option value="Card">Card</option>
              </select>
            </div>

            <div>
              <label className="mb-2 block text-sm font-medium">
                From Date
              </label>
              <input
                type="date"
                value={fromDate}
                onChange={(e) => setFromDate(e.target.value)}
                className="w-full rounded-xl border border-slate-200 px-3 py-2.5 outline-none"
              />
            </div>

            <div>
              <label className="mb-2 block text-sm font-medium">To Date</label>
              <input
                type="date"
                value={toDate}
                onChange={(e) => setToDate(e.target.value)}
                className="w-full rounded-xl border border-slate-200 px-3 py-2.5 outline-none"
              />
            </div>
          </div>

          {/* CATEGORY FILTER */}
          <div className="mt-4 max-w-md">
            <label className="mb-2 block text-sm font-medium">
              Expense Category
            </label>
            <select
              value={categoryFilter}
              onChange={(e) => setCategoryFilter(e.target.value)}
              className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 outline-none"
            >
              <option value="">All categories</option>
              {categoryOptions.map((c) => (
                <option key={c} value={c}>
                  {c}
                </option>
              ))}
            </select>
          </div>

          {/* TABLE */}
          <div className="mt-6 overflow-x-auto">
            <table className="min-w-[1050px] w-full text-sm">
              <thead>
                <tr className="border-b border-slate-200 text-slate-600">
                  <th className="px-4 py-3 text-left font-medium">Date</th>
                  <th className="px-4 py-3 text-left font-medium">
                    Description
                  </th>
                  <th className="px-4 py-3 text-left font-medium">
                    Expense Category
                  </th>
                  <th className="px-4 py-3 text-left font-medium">Type</th>
                  <th className="px-4 py-3 text-left font-medium">
                    Payment Method
                  </th>
                  <th className="px-4 py-3 text-right font-medium">Amount</th>
                  <th className="px-4 py-3 text-center font-medium">
                    Actions
                  </th>
                </tr>
              </thead>

              <tbody>
                {filteredExpenses.map((expense) => (
                  <tr
                    key={expense.TransactionID}
                    className="border-b border-slate-100 hover:bg-slate-50"
                  >
                    <td className="whitespace-nowrap px-4 py-4">
                      {formatDate(expense.ExpenseDate)}
                    </td>
                    <td className="px-4 py-4">
                      <div className="font-medium text-slate-900">
                        {expense.Description || "-"}
                      </div>
                      {expense.ReferenceNo && (
                        <div className="mt-1 text-xs text-slate-500">
                          Ref: {expense.ReferenceNo}
                        </div>
                      )}
                    </td>
                    <td className="px-4 py-4">
                      <span className="rounded-lg bg-amber-50 px-2.5 py-1 text-xs font-medium text-amber-700">
                        {expense.Category || "-"}
                      </span>
                    </td>
                    <td className="px-4 py-4">
                      <span className="rounded-lg bg-red-50 px-2.5 py-1 text-xs font-medium text-red-600">
                        Expense
                      </span>
                    </td>
                    <td className="px-4 py-4">
                      {expense.AccountName ||
                        expense.ToAccountName ||
                        expense.FromAccountName ||
                        "-"}
                    </td>
                    <td className="px-4 py-4 text-right font-semibold text-red-600">
                      Rs. {formatMoney(expense.Amount)}
                    </td>
                    <td className="px-4 py-4">
                      <div className="flex justify-center gap-2">
                        <button
                          type="button"
                          title="Edit"
                          className="rounded-lg border border-slate-200 p-2 hover:bg-slate-100"
                        >
                          <Pencil size={15} />
                        </button>
                        <button
                          type="button"
                          title="Delete"
                          onClick={() => deleteExpense(expense)}
                          disabled={loading}
                          className="rounded-lg border border-red-100 p-2 text-red-500 hover:bg-red-50 disabled:opacity-50"
                        >
                          <Trash2 size={15} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}

                {!loading && filteredExpenses.length === 0 && (
                  <tr>
                    <td
                      colSpan="7"
                      className="px-5 py-14 text-center text-slate-500"
                    >
                      No expense transactions found.
                    </td>
                  </tr>
                )}

                {loading && (
                  <tr>
                    <td
                      colSpan="7"
                      className="px-5 py-14 text-center text-slate-500"
                    >
                      Loading expenses...
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* =====================================================
          ADD EXPENSE MODAL
      ===================================================== */}
      {showModal && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/60 p-4">
          <div className="flex max-h-[90vh] w-full max-w-[675px] flex-col overflow-hidden rounded-2xl bg-white shadow-2xl">
            <div className="flex items-start justify-between border-b border-slate-100 px-6 py-5">
              <div>
                <h2 className="text-xl font-semibold text-slate-900">
                  Record New Expense
                </h2>
                <p className="mt-1 text-sm text-slate-500">
                  Add a new expense transaction
                </p>
              </div>
              <button
                type="button"
                onClick={closeModal}
                className="rounded-full p-1.5 text-slate-500 hover:bg-slate-100"
              >
                <X size={20} />
              </button>
            </div>

            <form
              onSubmit={saveExpense}
              className="overflow-y-auto px-6 py-5"
            >
              {/* FROM ACCOUNT */}
              <label className="mt-3 block text-sm font-medium">
                From Account <span className="ml-1 text-red-500">*</span>
              </label>
              <select
                value={form.fromAccountID}
                onChange={(e) => updateForm("fromAccountID", e.target.value)}
                className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-4 py-3 outline-none focus:border-amber-400"
              >
                <option value="">Select from account</option>
                {accounts.map((a) => (
                  <option key={a.AccountID} value={a.AccountID}>
                    {a.AccountName}
                    {a.AccountNumber ? ` - ${a.AccountNumber}` : ""}
                  </option>
                ))}
              </select>

              {/* TO ACCOUNT */}
              <label className="mt-5 block text-sm font-medium">
                To Account <span className="ml-1 text-red-500">*</span>
              </label>
              <select
                value={form.toAccountID}
                onChange={(e) => updateForm("toAccountID", e.target.value)}
                className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-4 py-3 outline-none focus:border-amber-400"
              >
                <option value="">Select to account</option>
                {accounts.map((a) => (
                  <option key={a.AccountID} value={a.AccountID}>
                    {a.AccountName}
                    {a.AccountNumber ? ` - ${a.AccountNumber}` : ""}
                  </option>
                ))}
              </select>

              {/* CATEGORY */}
              <label className="mt-5 block text-sm font-medium">
                Expense Category
              </label>
              <div className="relative mt-2">
                <button
                  type="button"
                  onClick={() => setCategoryOpen((p) => !p)}
                  className="flex w-full items-center justify-between rounded-xl border border-slate-200 bg-white px-4 py-3 text-left text-sm outline-none focus:border-amber-400"
                >
                  <span className={form.category ? "" : "text-slate-400"}>
                    {form.category || "Select category"}
                  </span>
                  <ChevronDown size={17} className="text-slate-400" />
                </button>

                {categoryOpen && (
                  <div className="absolute z-20 mt-1 w-full rounded-xl border border-slate-200 bg-white shadow-lg">
                    <div className="border-b border-slate-100 p-2">
                      <input
                        autoFocus
                        type="text"
                        value={categorySearch}
                        onChange={(e) => setCategorySearch(e.target.value)}
                        placeholder="Search category..."
                        className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none"
                      />
                    </div>
                    <div className="max-h-48 overflow-y-auto">
                      {filteredCategories.length === 0 ? (
                        <div className="px-4 py-3 text-center text-sm text-slate-400">
                          No categories
                        </div>
                      ) : (
                        filteredCategories.map((c) => (
                          <button
                            key={c}
                            type="button"
                            onClick={() => selectCategory(c)}
                            className={`block w-full px-4 py-2 text-left text-sm hover:bg-amber-50 ${
                              form.category === c ? "bg-amber-50" : ""
                            }`}
                          >
                            {c}
                          </button>
                        ))
                      )}
                    </div>
                  </div>
                )}
              </div>

              {/* AMOUNT */}
              <label className="mt-5 block text-sm font-medium">
                Amount <span className="ml-1 text-red-500">*</span>
              </label>
              <input
                type="number"
                min="0.01"
                step="0.01"
                value={form.amount}
                onChange={(e) => updateForm("amount", e.target.value)}
                placeholder="0.00"
                className="mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 outline-none focus:border-amber-400"
              />

              {/* DESCRIPTION */}
              <label className="mt-5 block text-sm font-medium">
                Expense Description
              </label>
              <textarea
                rows="3"
                value={form.description}
                onChange={(e) => updateForm("description", e.target.value)}
                placeholder="Enter expense description"
                className="mt-2 w-full resize-none rounded-xl border border-slate-200 px-4 py-3 outline-none focus:border-amber-400"
              />

              {/* REFERENCE */}
              <label className="mt-5 block text-sm font-medium">
                Reference Number{" "}
                <span className="ml-1 font-normal text-slate-400">
                  (Optional)
                </span>
              </label>
              <input
                type="text"
                value={form.referenceNo}
                onChange={(e) => updateForm("referenceNo", e.target.value)}
                placeholder="Enter reference number"
                className="mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 outline-none focus:border-amber-400"
              />

              {/* EXPENSE DATE */}
              <label className="mt-5 block text-sm font-medium">
                Expense Date
              </label>
              <input
                type="date"
                value={form.expenseDate}
                onChange={(e) => updateForm("expenseDate", e.target.value)}
                className="mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 outline-none focus:border-amber-400"
              />

              {/* ERROR */}
              {error && (
                <div className="mt-4 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-600">
                  {error}
                </div>
              )}

              {/* BUTTONS */}
              <div className="mt-6 flex justify-end gap-3 border-t border-slate-100 pt-5">
                <button
                  type="button"
                  onClick={closeModal}
                  disabled={saving}
                  className="rounded-xl border border-slate-200 px-5 py-3 font-medium hover:bg-slate-50 disabled:opacity-50"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={saving}
                  className="rounded-xl bg-amber-500 px-6 py-3 font-semibold text-white hover:bg-amber-600 disabled:opacity-50"
                >
                  {saving ? "Saving..." : "Record Expense"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ExpenseManagement;