// AccountLedger.jsx
// ============================================================
// Account Ledger — Firestore version
// ------------------------------------------------------------
// View detailed account statements with:
//   - Account selection
//   - Date range filtering (defaults to 1 Jan → today)
//   - Filter type (all / credit / debit)
//   - Summary cards (balance, credits, debits, net movement)
//   - Running-balance statement table
//
// Firestore collections used:
//   - Accounts               (account list + StoredBalance)
//   - AccountTransactions    (ledger rows)
//
// Opening balance is computed client-side from transactions
// with date < fromDate, since Firestore can't SUM server-side.
// ============================================================

import React, { useCallback, useEffect, useMemo, useState } from "react";
import {
  Filter,
  CalendarDays,
  ChevronDown,
  FileText,
  TrendingUp,
  TrendingDown,
  RefreshCw,
} from "lucide-react";

import {
  COLLECTIONS,
  listCollection,
} from "../lib/firestore.js";

/* ==================================================
   HELPERS
   ================================================== */

function formatMoney(value) {
  const amount = Number(value || 0);

  return `Rs.${amount.toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
}

function formatDate(value) {
  if (!value) return "-";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return "-";
  }

  return date.toLocaleDateString("en-GB");
}

/** Local-date → "YYYY-MM-DD" (avoids the UTC shift of toISOString). */
function toISODate(date) {
  const pad = (n) => String(n).padStart(2, "0");

  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(
    date.getDate()
  )}`;
}

/**
 * Normalizes any value (Firestore Timestamp, Date, ISO string)
 * to a plain "YYYY-MM-DD" string for safe lexicographic
 * comparison. Returns null if unparseable.
 */
function toDateOnly(value) {
  if (!value) return null;

  // Firestore Timestamp
  if (typeof value?.toDate === "function") {
    return toDateOnly(value.toDate());
  }

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return null;

  return toISODate(date);
}

/** Default range: 1 Jan of the current year → today. */
function defaultFromDate() {
  const now = new Date();
  return toISODate(new Date(now.getFullYear(), 0, 1));
}

function defaultToDate() {
  return toISODate(new Date());
}

/**
 * Normalises a Firestore account doc so the rest of the
 * component can always use PascalCase fields.
 */
function normalizeAccount(raw) {
  if (!raw) return null;

  return {
    AccountID: raw.id ?? raw.AccountID ?? raw.id ?? null,
    AccountName: raw.AccountName ?? raw.name ?? "",
    AccountType: raw.AccountType ?? raw.type ?? "",
    DetailType: raw.DetailType ?? raw.detailType ?? "",
    Description: raw.Description ?? raw.description ?? "",
    StoredBalance: Number(raw.StoredBalance ?? raw.balance ?? 0),
    IsActive: raw.IsActive ?? raw.status ?? true,
  };
}

/**
 * Normalises a Firestore transaction doc.
 * Returns `dateOnly` as a pre-computed "YYYY-MM-DD" for fast
 * range comparison, while keeping `TransactionDate` original
 * for display.
 */
function normalizeTransaction(raw) {
  const rawDate = raw.TransactionDate ?? raw.date ?? null;

  return {
    LedgerID: raw.id ?? raw.LedgerID ?? null,
    TransactionDate: rawDate,
    dateOnly: toDateOnly(rawDate),
    ReferenceNo: raw.ReferenceNo ?? raw.referenceNo ?? "",
    Description: raw.Description ?? raw.description ?? "",
    TransactionType: raw.TransactionType ?? raw.transactionType ?? "",
    Debit: Number(raw.Debit ?? raw.debit ?? 0),
    Credit: Number(raw.Credit ?? raw.credit ?? 0),
  };
}

/* ==================================================
   SUMMARY CARD
   ================================================== */

function SummaryCard({ title, value, subtitle, type }) {
  let valueClass = "text-gray-950";

  if (type === "credit") valueClass = "text-green-600";
  if (type === "debit") valueClass = "text-red-600";
  if (type === "balance") {
    valueClass = Number(value) < 0 ? "text-red-600" : "text-gray-950";
  }
  if (type === "movement") {
    valueClass = Number(value) < 0 ? "text-red-600" : "text-green-600";
  }

  return (
    <div className="rounded-xl border border-gray-300 bg-white p-6 shadow-sm">
      <div className="flex items-center justify-between">
        <p className="text-sm font-medium text-gray-600">{title}</p>

        {type === "credit" && (
          <TrendingUp size={18} className="text-green-600" />
        )}
        {type === "debit" && (
          <TrendingDown size={18} className="text-red-600" />
        )}
      </div>

      <p className={`mt-3 text-2xl font-bold ${valueClass}`}>
        {formatMoney(value)}
      </p>

      {subtitle && (
        <p className="mt-1 text-xs text-gray-500">{subtitle}</p>
      )}
    </div>
  );
}

/* ==================================================
   MAIN COMPONENT
   ================================================== */

export default function AccountLedger() {
  const [accounts, setAccounts] = useState([]);
  const [accountId, setAccountId] = useState("");

  const [fromDate, setFromDate] = useState(defaultFromDate);
  const [toDate, setToDate] = useState(defaultToDate);
  const [filterType, setFilterType] = useState("all");

  const [ledger, setLedger] = useState([]);

  const [summary, setSummary] = useState({
    openingBalance: 0,
    totalCredits: 0,
    totalDebits: 0,
    netMovement: 0,
    calculatedBalance: 0,
  });

  const [loadingAccounts, setLoadingAccounts] = useState(false);
  const [loadingLedger, setLoadingLedger] = useState(false);
  const [error, setError] = useState("");

  /* ==================================================
     DERIVED ACCOUNT
     --------------------------------------------------
     Read directly from the accounts array — no separate
     state needed, avoids stale references.
  ================================================== */

  const account = useMemo(() => {
    if (!accountId) return null;
    return (
      accounts.find((a) => String(a.AccountID) === String(accountId)) ||
      null
    );
  }, [accounts, accountId]);

  /* ==================================================
     LOAD ACCOUNTS
  ================================================== */

  const loadAccounts = useCallback(async () => {
    try {
      setLoadingAccounts(true);
      setError("");

      const rows = await listCollection(COLLECTIONS.ACCOUNTS, {
        where: [["IsDelete", "==", 0]],
      });

      const normalized = rows
        .map(normalizeAccount)
        .filter((a) => a.AccountID != null)
        .sort((a, b) =>
          String(a.AccountName).localeCompare(String(b.AccountName))
        );

      setAccounts(normalized);
    } catch (err) {
      console.error("LOAD ACCOUNTS ERROR:", err);
      setError(err.message || "Failed to load accounts");
      setAccounts([]);
    } finally {
      setLoadingAccounts(false);
    }
  }, []);

  /* ==================================================
     LOAD LEDGER
     --------------------------------------------------
     Loads all transactions for the account, then:
       1. Computes opening balance from tx before fromDate
       2. Filters period transactions in [fromDate, toDate]
       3. Applies filterType (all / credit / debit)
     This avoids composite indexes on AccountID + date range.
  ================================================== */

  const loadLedger = useCallback(async () => {
    if (!accountId) {
      setLedger([]);
      setSummary({
        openingBalance: 0,
        totalCredits: 0,
        totalDebits: 0,
        netMovement: 0,
        calculatedBalance: 0,
      });
      return;
    }

    try {
      setLoadingLedger(true);
      setError("");

      const rows = await listCollection(COLLECTIONS.ACCOUNT_TRANSACTIONS, {
        where: [
          ["AccountID", "==", accountId],
          ["IsDelete", "==", 0],
        ],
      });

      const normalized = rows
        .map(normalizeTransaction)
        .filter((t) => t.LedgerID);

      const fromStr = fromDate || "";
      const toStr = toDate || "";

      /* ---- 1. OPENING BALANCE (tx before fromDate) ---- */

      const openingBalance = normalized
        .filter((t) => {
          if (!t.dateOnly) return false;
          if (fromStr && t.dateOnly >= fromStr) return false;
          return true;
        })
        .reduce((sum, t) => sum + t.Credit - t.Debit, 0);

      /* ---- 2. PERIOD TRANSACTIONS (fromDate → toDate) ---- */

      const periodTx = normalized
        .filter((t) => {
          if (!t.dateOnly) return false;
          if (fromStr && t.dateOnly < fromStr) return false;
          if (toStr && t.dateOnly > toStr) return false;
          return true;
        })
        .sort((a, b) => {
          const da = a.dateOnly || "";
          const db = b.dateOnly || "";
          return da < db ? -1 : da > db ? 1 : 0;
        });

      /* ---- 3. APPLY FILTER TYPE ---- */

      const filtered =
        filterType === "credit"
          ? periodTx.filter((t) => t.Credit > 0)
          : filterType === "debit"
          ? periodTx.filter((t) => t.Debit > 0)
          : periodTx;

      /* ---- 4. SUMMARY ---- */

      const totalCredits = filtered.reduce(
        (s, t) => s + Number(t.Credit || 0),
        0
      );
      const totalDebits = filtered.reduce(
        (s, t) => s + Number(t.Debit || 0),
        0
      );
      const netMovement = totalCredits - totalDebits;

      setLedger(filtered);

      setSummary({
        openingBalance,
        totalCredits,
        totalDebits,
        netMovement,
        calculatedBalance: openingBalance + netMovement,
      });
    } catch (err) {
      console.error("LOAD LEDGER ERROR:", err);
      setError(err.message || "Failed to load ledger");
      setLedger([]);
    } finally {
      setLoadingLedger(false);
    }
  }, [accountId, fromDate, toDate, filterType]);

  /* ==================================================
     INITIAL LOAD
  ================================================== */

  useEffect(() => {
    loadAccounts();
  }, [loadAccounts]);

  /* ==================================================
     AUTO SELECT FIRST ACCOUNT
  ================================================== */

  useEffect(() => {
    if (accounts.length > 0 && !accountId) {
      const firstId = accounts[0].AccountID;
      if (firstId != null) {
        setAccountId(String(firstId));
      }
    }
  }, [accounts, accountId]);

  /* ==================================================
     RELOAD LEDGER WHEN FILTERS CHANGE
  ================================================== */

  useEffect(() => {
    if (accountId) {
      loadLedger();
    }
  }, [loadLedger, accountId]);

  /* ==================================================
     CURRENT BALANCE
  ================================================== */

  const currentBalance = useMemo(() => {
    if (!account) return 0;
    return Number(account.StoredBalance || 0);
  }, [account]);

  /* ==================================================
     RENDER
  ================================================== */

  return (
    <div className="min-h-screen bg-white px-6 py-6 md:px-8">
      {/* HEADER */}
      <div>
        <h1 className="text-3xl font-bold text-gray-950">Account Ledger</h1>
        <p className="mt-1 text-base text-gray-500">
          View detailed account statements
        </p>
      </div>

      {/* ERROR */}
      {error && (
        <div className="mt-5 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
          {error}
        </div>
      )}

      {/* FILTERS */}
      <div className="mt-6 rounded-2xl border border-gray-300 bg-white p-6 shadow-sm">
        <div className="mb-6 flex items-center gap-2">
          <Filter size={21} className="text-gray-700" />
          <h2 className="text-xl font-bold text-gray-900">Filters</h2>
        </div>

        <div className="grid gap-4 lg:grid-cols-4">
          {/* Account */}
          <div>
            <label className="mb-2 block text-sm font-medium text-gray-900">
              Account
            </label>

            <div className="relative">
              <select
                value={accountId}
                onChange={(e) => setAccountId(e.target.value)}
                disabled={loadingAccounts}
                className="h-10 w-full appearance-none rounded-xl border border-gray-200 bg-white px-3 pr-10 text-sm outline-none focus:border-orange-500 focus:ring-2 focus:ring-orange-100"
              >
                <option value="">
                  {loadingAccounts ? "Loading accounts..." : "Select account"}
                </option>

                {accounts.map((item) => (
                  <option key={item.AccountID} value={item.AccountID}>
                    {item.AccountName}
                  </option>
                ))}
              </select>

              <ChevronDown
                size={18}
                className="pointer-events-none absolute right-3 top-2.5 text-gray-500"
              />
            </div>
          </div>

          {/* From Date */}
          <div>
            <label className="mb-2 block text-sm font-medium text-gray-900">
              From Date
            </label>

            <div className="relative">
              <input
                type="date"
                value={fromDate}
                onChange={(e) => setFromDate(e.target.value)}
                className="h-10 w-full rounded-xl border border-gray-200 bg-white px-3 pr-10 text-sm outline-none focus:border-orange-500 focus:ring-2 focus:ring-orange-100"
              />

              <CalendarDays
                size={16}
                className="pointer-events-none absolute right-3 top-3 text-gray-500"
              />
            </div>
          </div>

          {/* To Date */}
          <div>
            <label className="mb-2 block text-sm font-medium text-gray-900">
              To Date
            </label>

            <div className="relative">
              <input
                type="date"
                value={toDate}
                min={fromDate || undefined}
                onChange={(e) => setToDate(e.target.value)}
                className="h-10 w-full rounded-xl border border-gray-200 bg-white px-3 pr-10 text-sm outline-none focus:border-orange-500 focus:ring-2 focus:ring-orange-100"
              />

              <CalendarDays
                size={16}
                className="pointer-events-none absolute right-3 top-3 text-gray-500"
              />
            </div>
          </div>

          {/* Filter Type */}
          <div>
            <label className="mb-2 block text-sm font-medium text-gray-900">
              Filter Type
            </label>

            <div className="relative">
              <select
                value={filterType}
                onChange={(e) => setFilterType(e.target.value)}
                className="h-10 w-full appearance-none rounded-xl border border-gray-200 bg-white px-3 pr-10 text-sm outline-none focus:border-orange-500 focus:ring-2 focus:ring-orange-100"
              >
                <option value="all">All Transactions</option>
                <option value="credit">Credits Only</option>
                <option value="debit">Debits Only</option>
              </select>

              <ChevronDown
                size={18}
                className="pointer-events-none absolute right-3 top-2.5 text-gray-500"
              />
            </div>
          </div>
        </div>
      </div>

      {/* SUMMARY */}
      {account && (
        <div className="mt-5 grid gap-4 md:grid-cols-2 lg:grid-cols-4">
          <SummaryCard
            title="Current Balance"
            value={currentBalance}
            subtitle={account.AccountType}
            type="balance"
          />

          <SummaryCard
            title="Total Credits"
            value={summary.totalCredits}
            subtitle={`${
              ledger.filter((x) => x.Credit > 0).length
            } transactions`}
            type="credit"
          />

          <SummaryCard
            title="Total Debits"
            value={summary.totalDebits}
            subtitle={`${ledger.filter((x) => x.Debit > 0).length} transactions`}
            type="debit"
          />

          <SummaryCard
            title="Net Movement"
            value={summary.netMovement}
            subtitle="Period difference"
            type="movement"
          />
        </div>
      )}

      {/* STATEMENT */}
      {account && (
        <div className="mt-6 rounded-2xl border border-gray-300 bg-white shadow-sm">
          <div className="flex flex-col justify-between gap-4 border-b border-gray-200 px-6 py-6 md:flex-row md:items-center">
            <div className="flex items-center gap-3">
              <FileText size={22} className="text-gray-700" />

              <div>
                <h2 className="text-2xl font-bold text-gray-950">
                  Account Statement - {account.AccountName}
                </h2>

                <p className="mt-1 text-sm text-gray-500">
                  {account.DetailType || account.AccountType}
                </p>
              </div>
            </div>

            <div className="text-left md:text-right">
              <p className="text-sm text-gray-500">Current Balance</p>

              <p
                className={`text-xl font-bold ${
                  currentBalance < 0 ? "text-red-600" : "text-gray-950"
                }`}
              >
                {formatMoney(currentBalance)}
              </p>
            </div>
          </div>

          {loadingLedger && (
            <div className="flex items-center justify-center gap-2 px-6 py-12 text-sm text-gray-500">
              <RefreshCw size={18} className="animate-spin" />
              Loading transactions...
            </div>
          )}

          {!loadingLedger && (
            <div className="overflow-x-auto">
              <table className="w-full min-w-[900px] border-collapse">
                <thead>
                  <tr className="border-b border-gray-300 bg-gray-50">
                    <th className="px-5 py-4 text-left text-sm font-medium text-gray-600">
                      Date
                    </th>
                    <th className="px-5 py-4 text-left text-sm font-medium text-gray-600">
                      Reference
                    </th>
                    <th className="px-5 py-4 text-left text-sm font-medium text-gray-600">
                      Description
                    </th>
                    <th className="px-5 py-4 text-right text-sm font-medium text-gray-600">
                      Debit
                    </th>
                    <th className="px-5 py-4 text-right text-sm font-medium text-gray-600">
                      Credit
                    </th>
                    <th className="px-5 py-4 text-right text-sm font-medium text-gray-600">
                      Balance
                    </th>
                  </tr>
                </thead>

                <tbody>
                  {/* Opening Balance */}
                  <tr className="border-b border-gray-200 bg-gray-50">
                    <td
                      colSpan="5"
                      className="px-5 py-4 text-sm font-semibold text-gray-700"
                    >
                      Opening Balance
                    </td>
                    <td className="px-5 py-4 text-right font-mono text-sm font-semibold">
                      {formatMoney(summary.openingBalance)}
                    </td>
                  </tr>

                  {(() => {
                    let runningBalance = Number(summary.openingBalance || 0);

                    return ledger.map((row) => {
                      runningBalance += row.Credit - row.Debit;

                      return (
                        <tr
                          key={row.LedgerID}
                          className="border-b border-gray-200 hover:bg-gray-50"
                        >
                          <td className="px-5 py-4 text-sm text-gray-700">
                            {formatDate(row.TransactionDate)}
                          </td>

                          <td className="px-5 py-4 text-sm font-medium text-gray-900">
                            {row.ReferenceNo || "-"}
                          </td>

                          <td className="px-5 py-4 text-sm text-gray-700">
                            {row.Description || row.TransactionType || "-"}
                          </td>

                          <td className="px-5 py-4 text-right font-mono text-sm text-red-600">
                            {row.Debit > 0 ? formatMoney(row.Debit) : "-"}
                          </td>

                          <td className="px-5 py-4 text-right font-mono text-sm text-green-600">
                            {row.Credit > 0 ? formatMoney(row.Credit) : "-"}
                          </td>

                          <td
                            className={`px-5 py-4 text-right font-mono text-sm font-semibold ${
                              runningBalance < 0
                                ? "text-red-600"
                                : "text-gray-900"
                            }`}
                          >
                            {formatMoney(runningBalance)}
                          </td>
                        </tr>
                      );
                    });
                  })()}

                  {/* Empty state */}
                  {ledger.length === 0 && (
                    <tr>
                      <td
                        colSpan="6"
                        className="px-5 py-12 text-center text-sm text-gray-500"
                      >
                        No transactions found for{" "}
                        <span className="font-medium text-gray-700">
                          {fromDate} → {toDate}
                        </span>
                        {filterType !== "all" && (
                          <>
                            {" "}
                            (filter:{" "}
                            <span className="font-medium text-gray-700">
                              {filterType}
                            </span>
                            )
                          </>
                        )}
                        .
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* NO ACCOUNT */}
      {!account && !loadingAccounts && (
        <div className="mt-6 rounded-2xl border border-gray-300 bg-white px-6 py-16 text-center">
          <FileText size={40} className="mx-auto text-gray-300" />

          <h2 className="mt-4 text-lg font-semibold text-gray-900">
            Select an account
          </h2>

          <p className="mt-1 text-sm text-gray-500">
            Select an account above to view its ledger statement.
          </p>
        </div>
      )}
    </div>
  );
}