import React, { useState } from "react";

const Invoice = () => {
  const [sections] = useState([]);
  const [paid] = useState(0);

  const total = sections.reduce((sum, section) => {
    return sum + ((section.item?.SellingPrice || 0) * section.qty);
  }, 0);

  const discount = sections.reduce((sum, section) => {
    const price = section.item?.SellingPrice || 0;
    const qty = section.qty || 0;
    const disc = section.item?.FixedDiscountPercentage || 0;
    return sum + ((price * qty) * disc / 100);
  }, 0);

  const subtotal = total - discount;
  const totaldiscount = sections.reduce((sum, section) => {
    return sum + (section.item?.FixedDiscountPercentage || 0);
  }, 0);
  const Balance = paid - subtotal;
  const totalqty = sections.reduce((sum, section) => {
    return sum + (section.qty || 0);
  }, 0);

  return (
    <div className="p-7 flex-1 flex flex-col py-20 items-center">
      <h1 className="text-2xl font-bold py-5">JMF</h1>
      <p>galle road dam street colombo</p>
      <p>0777766666</p>
      <div className="relative border-t pb-2 pt-2 mb-3">
        <ul className="divide-y">
          <li className="grid grid-cols-[2fr_1fr_1fr_1fr_0.5fr] gap-2 px-2 py-2 border-b text-xs font-semibold text-gray-600">
            <span className="text-sm font-medium">ProductCode</span>
            <span className="text-sm font-medium">Product</span>
            <span className="text-sm font-medium">Discount</span>
            <span className="text-sm font-medium">Qty</span>
            <span className="text-sm font-medium">Price</span>
          </li>
        </ul>
        <div className="flex-1 overflow-y-auto px-2 scrollbar-thin scrollbar-thumb-gray-400 scrollbar-track-gray-100">
          <ul className="divide-y">
            {sections.map((section) => (
              <li
                key={section.id}
                className="flex justify-between items-center py-3 px-2 hover:bg-gray-100"
              >
                <span className="text-sm font-medium">
                  {section.item?.ProductCode}
                </span>
                <span className="text-sm font-medium">
                  {section.item?.ProductName}
                </span>
                <span className="text-sm font-medium">
                  {section.item?.FixedDiscountPercentage + "%"}
                </span>
                <span className="text-sm font-medium">{section.qty}</span>
                <span className="text-sm font-medium">
                  {section.item?.SellingPrice}
                </span>
              </li>
            ))}
          </ul>
        </div>

        {/* FOOTER SUMMARY */}
        <div className="border-t pt-3 mt-3 space-y-2">
          <div className="flex justify-between text-sm font-semibold">
            <span>Total Items</span>
            <span>{sections.length}</span>
          </div>
          <div className="flex justify-between text-sm font-semibold">
            <span>Total Qty</span>
            <span>{totalqty}</span>
          </div>
        </div>
        <div className="border-t pt-3 mt-3 space-y-2">
          <div className="flex justify-between text-sm font-semibold">
            <span>Discount Percentage</span>
            <span>{totaldiscount + "%"}</span>
          </div>
          <div className="flex justify-between text-sm font-semibold">
            <span>Discount</span>
            <span>{discount}</span>
          </div>
          <div className="flex justify-between text-sm font-semibold">
            <span>Total</span>
            <span>{subtotal}</span>
          </div>
          <div className="border-t pt-3 mt-3 space-y-2">
            <div className="flex justify-between text-sm font-semibold">
              <span>Paid</span>
              <span>{paid}</span>
            </div>
            <div className="flex justify-between text-sm font-semibold">
              <span>Balance</span>
              <span>{Balance}</span>
            </div>
          </div>
        </div>

        <button
          onClick={() => window.print()}
          className="absolute text-gray-500 hover:text-black"
        >
          ✕
        </button>
      </div>
    </div>
  );
};

export default Invoice;
