// src/context/PermissionsContext.jsx
import React, {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  useCallback,
} from "react";

import {
  collection,
  query,
  where,
  doc,
  getDocs,
  getDoc,
  getDocsFromCache,
} from "firebase/firestore";

import { db } from "../firebase";
import { AuthContext } from "../pos/SERVER/AuthContext.js";

export const PermissionsContext = createContext(null);

const COL_PERMISSIONS = "cashierpermissions";
const COL_CASHIER = "cashier";
const CACHE_PREFIX = "pos.permissions";
const CACHE_MAX_AGE_MS = 1000 * 60 * 60 * 24 * 30; // 30 days

// ---- Last-resort fallback ---------------------------------------------------
// Used ONLY when: no permissionsOverride, no localStorage cache, network
// unreachable, and Firestore's offline cache is empty (i.e. a first-ever
// offline launch on this device). Grant the minimum needed to render the
// app shell + an offline banner. Never grant business actions
// (create/edit/delete, discounts, credit, cost price) here.
//
// Customize the module names to match your app. Add entries as:
//   { id: "__offline__<n>", ModuleName: "<ModuleName>", CanView: true }
const OFFLINE_FALLBACK_ROWS = [
  { id: "__offline__dashboard", ModuleName: "Dashboard", CanView: true },
];

const norm = (value) => String(value ?? "").trim().toLowerCase();

const ACTION_TO_COLUMN = {
  view: "CanView",
  add: "CanAdd",
  edit: "CanEdit",
  delete: "CanDelete",
  print: "CanPrint",
  canview: "CanView",
  canadd: "CanAdd",
  canedit: "CanEdit",
  candelete: "CanDelete",
  canprint: "CanPrint",
  costprice: "CanViewCostPrice",
  sellingprice: "CanViewSellingPrice",
  profit: "CanViewProfit",
  creditlimit: "CanViewCreditLimit",
  minimumdiscount: "CanViewMinimumDiscount",
  maximumdiscount: "CanViewMaximumDiscount",
  purchaselimit: "CanViewPurchaseLimit",
  canviewcostprice: "CanViewCostPrice",
  canviewsellingprice: "CanViewSellingPrice",
  canviewprofit: "CanViewProfit",
  canviewcreditlimit: "CanViewCreditLimit",
  canviewminimumdiscount: "CanViewMinimumDiscount",
  canviewmaximumdiscount: "CanViewMaximumDiscount",
  canviewpurchaselimit: "CanViewPurchaseLimit",
};

const FIELD_TO_COLUMN = {
  costprice: "CanViewCostPrice",
  sellingprice: "CanViewSellingPrice",
  profit: "CanViewProfit",
  creditlimit: "CanViewCreditLimit",
  minimumdiscount: "CanViewMinimumDiscount",
  maximumdiscount: "CanViewMaximumDiscount",
  purchaselimit: "CanViewPurchaseLimit",
};

function resolveActionColumn(action) {
  if (!action) return "CanView";
  const key = norm(action);
  return ACTION_TO_COLUMN[key] || String(action);
}

function resolveFieldColumn(field) {
  if (!field) return null;
  return FIELD_TO_COLUMN[norm(field)] || null;
}

function isGranted(value) {
  if (value === true) return true;
  if (value === false || value == null) return false;
  if (typeof value === "number") return value !== 0;
  if (typeof value === "string") {
    const normalized = value.trim().toLowerCase();
    return (
      normalized !== "" &&
      normalized !== "0" &&
      normalized !== "false" &&
      normalized !== "no"
    );
  }
  return Boolean(value);
}

function rowIsActive(row) {
  if (!row) return false;
  if (row.IsDelete === true || row.IsDelete === 1 || row.IsDelete === "1")
    return false;
  if (row.IsActive === false || row.IsActive === 0 || row.IsActive === "0")
    return false;
  return true;
}

function isOfflineError(error) {
  const code = error?.code || "";
  const message = String(error?.message || error || "").toLowerCase();
  return (
    code === "unavailable" ||
    code === "deadline-exceeded" ||
    message.includes("offline") ||
    message.includes("unavailable") ||
    message.includes("failed to get document") ||
    message.includes("could not reach")
  );
}

function pickCashierId(...sources) {
  for (const source of sources) {
    if (source == null) continue;

    let value = source;
    if (typeof value === "object") {
      value =
        source.CashierID ??
        source.CashierId ??
        source.cashierID ??
        source.cashierId ??
        source.UserID ??
        source.userID;
    }
    if (value == null || String(value).trim() === "") continue;

    if (typeof value?.id === "string") value = value.id;

    const n = Number(value);
    if (Number.isFinite(n) && n > 0) return n;

    const s = String(value).trim();
    if (s) return s;
  }
  return null;
}

function readLegacyUser() {
  try {
    const raw = localStorage.getItem("user");
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" ? parsed : null;
  } catch {
    return null;
  }
}

function cacheKeyFor(cashierId) {
  return `${CACHE_PREFIX}.${cashierId}`;
}

function readLocalCache(cashierId) {
  try {
    const raw = localStorage.getItem(cacheKeyFor(cashierId));
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!parsed || !Array.isArray(parsed.rows)) return null;
    if (
      parsed.cachedAt &&
      Date.now() - Number(parsed.cachedAt) > CACHE_MAX_AGE_MS
    ) {
      return null;
    }
    return parsed;
  } catch {
    return null;
  }
}

function writeLocalCache(cashierId, rows) {
  try {
    localStorage.setItem(
      cacheKeyFor(cashierId),
      JSON.stringify({ rows, cachedAt: Date.now() })
    );
  } catch {
    // ignore quota errors
  }
}

function documentToRow(snapshot) {
  return { id: snapshot.id, ...snapshot.data() };
}

function mergeRows(...rowGroups) {
  const rowsById = new Map();
  for (const rows of rowGroups) {
    for (const row of rows || []) {
      if (row?.id) rowsById.set(row.id, row);
    }
  }
  return [...rowsById.values()].filter(rowIsActive);
}

async function fetchPermissionRowsFromNetwork(cashierId) {
  const permissionsCollection = collection(db, COL_PERMISSIONS);
  const rows = [];

  const strId = String(cashierId);
  const numId = Number(cashierId);
  const values =
    Number.isFinite(numId) && numId > 0 ? [numId, strId] : [strId];

  let lastError = null;

  for (const value of values) {
    try {
      const snapshot = await getDocs(
        query(permissionsCollection, where("CashierID", "==", value))
      );
      snapshot.forEach((docSnap) => rows.push(documentToRow(docSnap)));
    } catch (err) {
      // If we already have rows from a previous sub-query, don't throw them
      // away over a secondary failure.
      if (rows.length > 0) break;
      if (isOfflineError(err)) throw err;
      lastError = lastError || err;
      console.warn(
        "[Permissions] where(CashierID==%o) failed:",
        value,
        err?.message || err
      );
    }
  }

  if (rows.length === 0) {
    try {
      const direct = await getDoc(doc(db, COL_PERMISSIONS, strId));
      if (direct.exists()) rows.push(documentToRow(direct));
    } catch (err) {
      if (isOfflineError(err)) throw err;
      lastError = lastError || err;
    }
  }

  if (rows.length === 0 && lastError && !isOfflineError(lastError)) {
    throw lastError;
  }

  return mergeRows(rows);
}

// Firestore's persistent cache is query-scoped: a query only resolves from
// cache if it has successfully run online at least once on this device.
// During initial mount, the multi-tab lock can still be settling and the
// first getDocsFromCache may return empty even when data exists — retry
// briefly before declaring a miss.
async function fetchPermissionRowsFromCache(cashierId, attempts = 3) {
  const permissionsCollection = collection(db, COL_PERMISSIONS);
  const strId = String(cashierId);
  const numId = Number(cashierId);
  const values =
    Number.isFinite(numId) && numId > 0 ? [numId, strId] : [strId];

  for (let attempt = 0; attempt < attempts; attempt++) {
    const rows = [];

    for (const value of values) {
      try {
        const snapshot = await getDocsFromCache(
          query(permissionsCollection, where("CashierID", "==", value))
        );
        snapshot.forEach((docSnap) => rows.push(documentToRow(docSnap)));
      } catch {
        // empty per-query cache — try the next variant
      }
    }

    if (rows.length === 0) {
      try {
        const direct = await getDoc(doc(db, COL_PERMISSIONS, strId));
        if (direct.exists() && direct.metadata?.fromCache) {
          rows.push(documentToRow(direct));
        }
      } catch {
        // ignore
      }
    }

    const merged = mergeRows(rows);
    if (merged.length > 0) return merged;

    // Let the tab-manager lock settle, then retry.
    if (attempt < attempts - 1) {
      await new Promise((resolve) => setTimeout(resolve, 150));
    }
  }

  return [];
}

async function resolveCashierIdSlow(email, uid) {
  if (typeof navigator !== "undefined" && navigator.onLine === false) {
    console.warn("[Permissions] offline — skipping slow CashierID resolution");
    return null;
  }
  if (!email && !uid) return null;

  const tryQuery = async (field, value) => {
    if (!value) return null;
    try {
      const snap = await getDocs(
        query(collection(db, COL_CASHIER), where(field, "==", value))
      );
      if (!snap.empty) {
        const d = snap.docs[0];
        const data = d.data();
        const cid = data.CashierID ?? data.CashierId ?? data.UserID ?? d.id;
        return pickCashierId(cid);
      }
    } catch (err) {
      if (!isOfflineError(err)) {
        console.warn(
          `[Permissions] cashier.${field} lookup failed:`,
          err?.message || err
        );
      }
    }
    return null;
  };

  if (email) {
    const variants = [
      ...new Set([email, email.toLowerCase(), email.toUpperCase()]),
    ];
    for (const field of ["Email", "email", "LogName", "UserName"]) {
      for (const value of variants) {
        const id = await tryQuery(field, value);
        if (id != null) return id;
      }
    }
  }
  if (uid) {
    for (const field of ["AuthUID", "authUid", "UID", "uid"]) {
      const id = await tryQuery(field, uid);
      if (id != null) return id;
    }
  }
  return null;
}

export function PermissionsProvider({
  cashierID,
  permissionsOverride,
  children,
}) {
  const authContext = useContext(AuthContext);
  const authUser = authContext?.user || null;
  const authLoading = authContext?.loading !== false;

  const authEmail = authUser?.email || authUser?.Email || "";
  const authUid = authUser?.uid || authUser?.UID || "";
  const authCashierId = pickCashierId(authUser);

  const isAdminUser = useMemo(() => {
    return (
      authUser?.Type === 1 ||
      authUser?.Type === "1" ||
      authUser?.Type === 0 ||
      authUser?.IsAdmin === true ||
      authUser?.isAdmin === true ||
      authUser?.Role === "admin" ||
      authUser?.role === "admin"
    );
  }, [authUser]);

  // Only use localStorage.user when auth has settled AND has no user.
  const legacyCashierId = useMemo(
    () => (authLoading || authUser ? null : pickCashierId(readLegacyUser())),
    [authLoading, authUser]
  );

  // Loud, actionable warning: this means the app is authorizing against a
  // stale CashierID from a prior session because no auth user exists. It is
  // NOT an authenticated session, and permissions will almost always come
  // back empty (which is what produces the "Network unreachable and no
  // cache available" log). Fix by ensuring the user is signed in before
  // rendering <PermissionsProvider>, or by removing the legacy fallback.
  useEffect(() => {
    if (legacyCashierId != null) {
      console.error(
        `[Permissions] FALLING BACK TO LEGACY CashierID=${legacyCashierId} ` +
          `from localStorage.user. No authenticated user. Permissions will ` +
          `almost certainly be empty. Ensure the user is signed in.`
      );
    }
  }, [legacyCashierId]);

  const fastCashierId = useMemo(
    () => pickCashierId(cashierID, authCashierId, legacyCashierId),
    [cashierID, authCashierId, legacyCashierId]
  );

  const [slowCashierId, setSlowCashierId] = useState(null);
  const slowAttemptedRef = useRef(new Set());

  // Stabilize permissionsOverride so an inline `permissionsOverride={[...]}`
  // from the parent does not re-trigger the load effect on every render.
  const overrideKey = useMemo(
    () =>
      Array.isArray(permissionsOverride)
        ? JSON.stringify(permissionsOverride)
        : null,
    [permissionsOverride]
  );
  const stableOverride = useMemo(
    () => (Array.isArray(permissionsOverride) ? permissionsOverride : null),
    // Compare by content, not reference:
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [overrideKey]
  );

  const [permissions, setPermissions] = useState(
    Array.isArray(permissionsOverride) ? permissionsOverride : []
  );
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [isStale, setIsStale] = useState(false);
  const [cachedAt, setCachedAt] = useState(null);
  const [isOffline, setIsOffline] = useState(
    typeof navigator !== "undefined" ? !navigator.onLine : false
  );
  const [retryTick, setRetryTick] = useState(0);

  const resolvedCashierId = fastCashierId ?? slowCashierId;

  useEffect(() => {
    setSlowCashierId(null);
    slowAttemptedRef.current.clear();
  }, [authUid]);

  useEffect(() => {
    const onOnline = () => {
      setIsOffline(false);
      setRetryTick((n) => n + 1);
    };
    const onOffline = () => setIsOffline(true);
    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);
    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  useEffect(() => {
    slowAttemptedRef.current.clear();
  }, [retryTick]);

  // Slow-path attempt — resolved once per (email|uid) after auth settles.
  useEffect(() => {
    if (Array.isArray(stableOverride)) return;
    if (fastCashierId != null) return;
    if (slowCashierId != null) return;
    if (authLoading) return;
    if (!authEmail && !authUid) return;

    const attemptKey = `${authEmail}|${authUid}`;
    if (slowAttemptedRef.current.has(attemptKey)) return;
    slowAttemptedRef.current.add(attemptKey);

    let cancelled = false;
    (async () => {
      const id = await resolveCashierIdSlow(authEmail, authUid);
      if (!cancelled && id != null) {
        console.info(
          `[Permissions] Slow-path resolved CashierID=${id} for ${attemptKey}`
        );
        setSlowCashierId(id);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [
    stableOverride,
    fastCashierId,
    slowCashierId,
    authEmail,
    authUid,
    authLoading,
    retryTick,
  ]);

  // Tier order:
  //   1. permissionsOverride prop
  //   2. localStorage cache (persistent, survives reloads)
  //   3. network getDocs (fresh data)
  //   4. Firestore persistent cache via getDocsFromCache (SDK-managed)
  //   5. hardcoded OFFLINE_FALLBACK_ROWS (first-ever offline launch only)
  useEffect(() => {
    let cancelled = false;

    async function load() {
      if (Array.isArray(stableOverride)) {
        setPermissions(stableOverride);
        setError("");
        setIsStale(false);
        setCachedAt(null);
        setLoading(false);
        return;
      }

      if (resolvedCashierId == null) {
        setPermissions([]);
        setError("CashierID not found");
        setIsStale(false);
        setCachedAt(null);
        setLoading(false);

        if (!authLoading && !authEmail && !authUid) {
          console.warn(
            "[Permissions] No cashier ID available (auth finished loading with no user)."
          );
        }
        return;
      }

      // Tier 2: localStorage cache
      const cached = readLocalCache(resolvedCashierId);
      const cachedRows = cached ? mergeRows(cached.rows || []) : [];
      const hasLocalCache = cachedRows.length > 0;

      if (hasLocalCache) {
        setPermissions(cachedRows);
        setCachedAt(cached.cachedAt || null);
        setIsStale(true);
        setError("");
        setLoading(false);
        console.info(
          `[Permissions] Cache hit: ${cachedRows.length} row(s) for CashierID=${resolvedCashierId}`
        );
      } else {
        setLoading(true);
      }

      const browserOnline =
        typeof navigator !== "undefined" ? navigator.onLine !== false : true;

      // Tier 3: network
      if (browserOnline) {
        try {
          const networkRows = await fetchPermissionRowsFromNetwork(
            resolvedCashierId
          );
          if (cancelled) return;

          if (networkRows.length > 0) {
            setPermissions(networkRows);
            setError("");
            setIsStale(false);
            setIsOffline(false);
            setCachedAt(Date.now());
            writeLocalCache(resolvedCashierId, networkRows);
            console.info(
              `[Permissions] Network refresh: ${networkRows.length} row(s) for CashierID=${resolvedCashierId}`
            );
            return;
          }

          if (hasLocalCache) {
            setIsStale(true);
          } else {
            // Server responded truthfully with 0 rows — respect it.
            setPermissions([]);
            setError("No permissions configured for this cashier.");
            setIsStale(false);
          }
          return;
        } catch (err) {
          if (cancelled) return;
          if (!isOfflineError(err)) {
            console.error("[Permissions] Network read failed:", err);
            if (!hasLocalCache) {
              setError(err?.message || "Unable to load permissions.");
            }
            return;
          }
          setIsOffline(true);
          setIsStale(true);
        }
      } else {
        setIsOffline(true);
        setIsStale(true);
      }

      // Tier 4: Firestore persistent cache (SDK-managed).
      let firestoreCached = [];
      try {
        firestoreCached = await fetchPermissionRowsFromCache(resolvedCashierId);
      } catch {
        // ignore — a cache read error is not actionable
      }
      if (cancelled) return;

      if (firestoreCached.length > 0) {
        setPermissions(firestoreCached);
        setCachedAt(Date.now());
        setIsStale(true);
        setError("");
        writeLocalCache(resolvedCashierId, firestoreCached);
        console.info(
          `[Permissions] Firestore cache hit: ${firestoreCached.length} row(s) for CashierID=${resolvedCashierId}`
        );
        setLoading(false);
        return;
      }

      // Tier 5: all real sources exhausted.
      if (!hasLocalCache) {
        // Give the UI a shell so it can render a banner instead of a blank
        // screen. Do NOT write this to the local cache — it is not
        // authoritative data and must be replaced as soon as a real read
        // succeeds.
        setPermissions(OFFLINE_FALLBACK_ROWS);
        setIsStale(true);
        setIsOffline(true);
        setError("Offline and no cached permissions available.");
        console.warn(
          "[Permissions] Network unreachable and no cache available for CashierID:",
          resolvedCashierId,
          "— using OFFLINE_FALLBACK_ROWS until connectivity is restored."
        );
      } else {
        // We had local cache but network and Firestore cache both failed.
        // Keep showing the cached rows; isStale is already true.
        setIsStale(true);
      }
      setLoading(false);
    }

    load();
    return () => {
      cancelled = true;
    };
  }, [
    resolvedCashierId,
    stableOverride,
    retryTick,
    authEmail,
    authUid,
    authLoading,
  ]);

  const index = useMemo(() => {
    const map = new Map();
    for (const row of permissions) {
      if (!rowIsActive(row)) continue;
      const moduleName = norm(row.ModuleName || row.PermissionName);
      if (!moduleName) continue;

      let entry = map.get(moduleName);
      if (!entry) {
        entry = { row, byName: new Map() };
        map.set(moduleName, entry);
      }
      if (norm(row.ModuleName) === moduleName) entry.row = row;

      const permissionName = norm(row.PermissionName);
      if (permissionName && !entry.byName.has(permissionName)) {
        entry.byName.set(permissionName, row);
      }
    }
    return map;
  }, [permissions]);

  const can = useCallback((moduleName, permissionNameOrAction, actionArg) => {
      if (isAdminUser) return true;
      if (!moduleName || permissions.length === 0) return false;
      const entry = index.get(norm(moduleName));
      if (!entry) return false;

      let permissionName = null;
      let action = "CanView";

      if (actionArg !== undefined) {
        permissionName = permissionNameOrAction || null;
        action = resolveActionColumn(actionArg);
      } else if (
        permissionNameOrAction &&
        ACTION_TO_COLUMN[norm(permissionNameOrAction)]
      ) {
        action = resolveActionColumn(permissionNameOrAction);
      } else if (permissionNameOrAction) {
        permissionName = permissionNameOrAction;
      }

      const row = permissionName
        ? entry.byName.get(norm(permissionName)) || entry.row
        : entry.row;

      return isGranted(row?.[action]);
    },
    [index, permissions.length, isAdminUser]
  );

  const canAny = useCallback((moduleName, action = "CanView") => {
      if (isAdminUser) return true;
      const entry = index.get(norm(moduleName));
      if (!entry) return false;
      return isGranted(entry.row?.[resolveActionColumn(action)]);
    },
    [index, isAdminUser]);

  const canViewField = useCallback((moduleName, field) => {
      if (isAdminUser) return true;
      const column = resolveFieldColumn(field);
      if (!column) return true;
      if (!moduleName) return false;
      const entry = index.get(norm(moduleName));
      if (!entry?.row) return false;
      const row = entry.row;
      if (column in row && row[column] != null) return isGranted(row[column]);
      return isGranted(row.CanView);
    },
    [index, isAdminUser]);

  const reload = useCallback(() => {
    setRetryTick((n) => n + 1);
  }, []);

  const contextValue = useMemo(
    () => ({
      permissions,
      cashierID: resolvedCashierId,
      loading,
      error,
      isOffline,
      isStale,
      cachedAt,
      reload,
      can,
      canAny,
      canViewField,
    }),
    [
      permissions,
      resolvedCashierId,
      loading,
      error,
      isOffline,
      isStale,
      cachedAt,
      reload,
      can,
      canAny,
      canViewField,
    ]
  );

  return (
    <PermissionsContext.Provider value={contextValue}>
      {children}
    </PermissionsContext.Provider>
  );
}

export function usePermissionsContext() {
  const context = useContext(PermissionsContext);
  if (!context) {
    throw new Error(
      "usePermissionsContext must be used inside <PermissionsProvider>."
    );
  }
  return context;
}