// Saleshistory.jsx — Firestore version
// ============================================================
// Firestore collections used:
//   - Sales       (one doc per invoice, embeds itemsList[])
//   - PosSettings (single document, ID "1" — for printing)
//
// Pagination note:
//   Firestore has no OFFSET, so we load the matching set once
//   (filtered server-side by payType), then do search + date
//   range + sort + paginate entirely client-side. This preserves
//   the original UX (page numbers, prev/next, total count).
//
//   If the collection grows past a few thousand docs, add
//   `where: [["RecDate", ">=", ...]]` and switch to
//   startAfter() cursors.
// ============================================================

import React, {
  useState,
  useEffect,
  useCallback,
  useContext,
} from "react";

import {
  Search,
  Calendar,
  Download,
  RefreshCw,
  ChevronLeft,
  ChevronRight,
  Printer,
  X,
  Edit,
} from "lucide-react";

import { COLLECTIONS, listCollection, getDocById } from "../lib/firestore.js";
import { AuthContext } from "../pos/SERVER/AuthContext.js";

/* ======================================================
   COLLECTIONS
====================================================== */

const SALES = COLLECTIONS?.SALES ?? "Sales";

const POS_SETTINGS_COLLECTION =
  COLLECTIONS?.POS_SETTINGS ?? "PosSettings";

const POS_SETTINGS_ID = "1";

/* ======================================================
   NORMALIZER
====================================================== */

const pick = (obj, ...keys) => {
  for (const key of keys) {
    if (obj && obj[key] !== undefined && obj[key] !== null) {
      return obj[key];
    }
  }
  return "";
};

const toNumber = (value) => {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
};

const normalizeSale = (raw) => ({
  ...raw,
  _docId: raw.id ?? raw._docId ?? "",
  Receipt: pick(raw, "Receipt", "receipt", "InvoiceNumber") || "",
  RecDate:
    raw.RecDate ??
    raw.recDate ??
    raw.InvoiceDate ??
    raw.CreatedAt ??
    null,
  Customer:
    pick(raw, "Customer", "customer", "CustomerName") ||
    "Walk-in",
  PayTypeID:
    pick(raw, "PayTypeID", "payTypeID", "PaymentMethod") || "",
  SaleTypeID:
    pick(raw, "SaleTypeID", "saleTypeID", "SaleType") || "",
  ItemCount: toNumber(
    pick(raw, "ItemCount", "itemCount", "ItemQty") ||
      (Array.isArray(raw.itemsList) ? raw.itemsList.length : 0)
  ),
  Amount: toNumber(
    pick(raw, "Amount", "amount", "TotalAmount")
  ),
  TotalAmount: toNumber(
    pick(raw, "TotalAmount", "totalAmount", "Amount")
  ),
  CustomerAddress:
    pick(raw, "CustomerAddress", "customerAddress") || "",
  CustomerPhone:
    pick(raw, "CustomerPhone", "customerPhone") || "",
  PaymentMethod:
    pick(raw, "PaymentMethod", "paymentMethod", "PayTypeID") || "",
  SaleTypeID_value:
    pick(raw, "SaleTypeID", "saleTypeID", "SaleType") || "",
  itemsList: Array.isArray(raw.itemsList)
    ? raw.itemsList
    : Array.isArray(raw.items)
      ? raw.items
      : [],
});

/* ======================================================
   COMPONENT
====================================================== */

const SalesHistory = () => {
  const { user } = useContext(AuthContext);
  const username = user?.username || "admin";

  const [allSales, setAllSales] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const [searchTerm, setSearchTerm] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const [payType, setPayType] = useState("All Payments");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  const [page, setPage] = useState(1);
  const limit = 10;

  const [selectedInvoice, setSelectedInvoice] = useState(null);
  const [invoiceDetails, setInvoiceDetails] = useState(null);
  const [loadingDetails, setLoadingDetails] = useState(false);
  const [printing, setPrinting] = useState(false);

  /* ======================================================
     SEARCH DEBOUNCE
  ====================================================== */

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedSearch(searchTerm);
      setPage(1);
    }, 500);

    return () => clearTimeout(handler);
  }, [searchTerm]);

  /* ======================================================
     LOAD ALL SALES  (Firestore)
  ====================================================== */

  const loadSales = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      // Server-side payType filter (falls back to full load
      // when "All Payments" is selected)
      const options =
        payType && payType !== "All Payments"
          ? {
              where: [
                ["PayTypeID", "==", payType],
                ["IsDelete", "==", 0],
              ],
            }
          : { where: [["IsDelete", "==", 0]] };

      const rows = await listCollection(SALES, options);

      setAllSales(rows.map(normalizeSale));
    } catch (err) {
      console.error("Error fetching sales history:", err);
      setError(
        err.message ||
          "Failed to load sales data. Please check your Firestore connection."
      );
    } finally {
      setLoading(false);
    }
  }, [payType]);

  /* ======================================================
     INITIAL LOAD + RELOAD ON PAYTYPE CHANGE
  ====================================================== */

  useEffect(() => {
    loadSales();
  }, [loadSales]);

  /* ======================================================
     CLIENT-SIDE FILTER + SORT + PAGINATE
  ====================================================== */

  const filteredSales = useCallback(() => {
    const q = debouncedSearch.trim().toLowerCase();

    let rows = allSales;

    // Date range
    if (startDate) {
      rows = rows.filter((s) => {
        const d = String(s.RecDate || "").slice(0, 10);
        return d && d >= startDate;
      });
    }

    if (endDate) {
      rows = rows.filter((s) => {
        const d = String(s.RecDate || "").slice(0, 10);
        return d && d <= endDate;
      });
    }

    // Search across Receipt / Customer / PaymentMethod
    if (q) {
      rows = rows.filter((s) => {
        const text = [
          s.Receipt,
          s.Customer,
          s.PayTypeID,
          s.SaleTypeID,
          s.PaymentMethod,
        ]
          .filter(Boolean)
          .join(" ")
          .toLowerCase();

        return text.includes(q);
      });
    }

    // Sort by RecDate descending
    rows = [...rows].sort((a, b) => {
      const da = new Date(a.RecDate || 0).getTime();
      const db = new Date(b.RecDate || 0).getTime();
      return db - da;
    });

    return rows;
  }, [allSales, debouncedSearch, startDate, endDate]);

  const filtered = filteredSales();
  const totalRecords = filtered.length;
  const totalPages = Math.max(1, Math.ceil(totalRecords / limit));

  // Keep page in range after filter changes
  useEffect(() => {
    if (page > totalPages) {
      setPage(totalPages);
    }
  }, [totalPages, page]);

  const invoices = filtered.slice(
    (page - 1) * limit,
    page * limit
  );

  /* ======================================================
     FETCH INVOICE DETAILS
     ------------------------------------------------------
     Uses the sale's Firestore doc id (a direct doc read,
     so it's a single round trip rather than a query).
  ====================================================== */

  const handleRowClick = async (invoice) => {
    setSelectedInvoice(invoice);
    setInvoiceDetails(null);
    setLoadingDetails(true);

    try {
      let fullSale = null;

      if (invoice._docId) {
        const row = await getDocById(SALES, invoice._docId);
        if (row) {
          fullSale = normalizeSale({ ...row, id: invoice._docId });
        }
      }

      // Fallback if _docId wasn't present
      if (!fullSale && Array.isArray(invoice.itemsList)) {
        fullSale = invoice;
      }

      setInvoiceDetails(fullSale);
    } catch (err) {
      console.error("Error fetching invoice details:", err);
      setInvoiceDetails(null);
    } finally {
      setLoadingDetails(false);
    }
  };

  /* ======================================================
     CLOSE DETAILS
  ====================================================== */

  const closeDetailsPanel = () => {
    setSelectedInvoice(null);
    setInvoiceDetails(null);
  };

  /* ======================================================
     FORMAT HELPERS  (unchanged)
  ====================================================== */

  const formatCurrency = (amount) => {
    const safeAmount = Number(amount) || 0;

    return new Intl.NumberFormat("en-LK", {
      style: "currency",
      currency: "LKR",
      minimumFractionDigits: 2,
    })
      .format(safeAmount)
      .replace("LKR", "Rs.");
  };

  const formatDate = (dateString) => {
    if (!dateString) return "N/A";

    const date = new Date(dateString);

    return date.toLocaleDateString("en-GB", {
      day: "2-digit",
      month: "2-digit",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  const getPaperWidth = (paperSize) => {
    const value = String(paperSize || "")
      .trim()
      .toUpperCase()
      .replace(/\s+/g, "");

    switch (value) {
      case "58":
      case "58MM":
        return "58mm";
      case "76":
      case "76MM":
        return "76mm";
      case "80":
      case "80MM":
        return "80mm";
      case "A5":
        return "148mm";
      case "A4":
        return "210mm";
      default:
        return "80mm";
    }
  };

  /* ======================================================
     PRINT  (Firestore for settings; rest unchanged)
  ====================================================== */

  const handlePrint = async () => {
    if (!invoiceDetails) {
      alert("Invoice details are not loaded yet.");
      return;
    }

    if (printing) return;

    setPrinting(true);

    try {
      /* ---------------------------------------------- */
      /* 1. POS SETTINGS  (Firestore)                    */
      /* ---------------------------------------------- */

      const settingsDoc = await getDocById(
        POS_SETTINGS_COLLECTION,
        POS_SETTINGS_ID
      );

      const posSettings = settingsDoc || {};

      const paperWidth = getPaperWidth(posSettings.PaperSize);

      /* ---------------------------------------------- */
      /* 2. INVOICE DATA                                 */
      /* ---------------------------------------------- */

      const receiptNo = invoiceDetails.Receipt || "";
      const invoiceDate = invoiceDetails.RecDate
        ? formatDate(invoiceDetails.RecDate)
        : "";

      const customer =
        invoiceDetails.Customer || "Walk-in Customer";

      const paymentMethod =
        invoiceDetails.PaymentMethod || "Cash";

      const saleType = invoiceDetails.SaleTypeID || "";

      const total = Number(invoiceDetails.TotalAmount) || 0;

      const items = Array.isArray(invoiceDetails.itemsList)
        ? invoiceDetails.itemsList
        : [];

      /* ---------------------------------------------- */
      /* 3. POS SETTINGS FIELDS                          */
      /* ---------------------------------------------- */

      const companyName = posSettings.CompanyName || "";
      const companyAddress = posSettings.CompanyAddress || "";
      const companyPhone = posSettings.CompanyPhone || "";
      const companyEmail = posSettings.CompanyEmail || "";
      const taxNumber = posSettings.TaxNumber || "";
      const invoiceTitle = posSettings.InvoiceTitle || "INVOICE";
      const invoiceHeader = posSettings.InvoiceHeader || "";
      const invoiceFooter = posSettings.InvoiceFooter || "";
      const invoiceNotes = posSettings.InvoiceNotes || "";
      const currency = posSettings.Currency || "LKR";

      const showCustomer = posSettings.ShowCustomer !== false;
      const showCustomerAddress =
        posSettings.ShowCustomerAddress === true;
      const showCustomerPhone =
        posSettings.ShowCustomerPhone === true;
      const showPaymentMethod =
        posSettings.ShowPaymentMethod !== false;
      const showDateTime = posSettings.ShowDateTime !== false;
      const showTax = posSettings.ShowTax === true;

      /* ---------------------------------------------- */
      /* 4. ITEM ROWS                                    */
      /* ---------------------------------------------- */

      const itemRows = items
        .map((item) => {
          const description = item.Descrip || "";
          const qty = Number(item.Qty) || 0;
          const price = Number(item.Price) || 0;
          const amount = Number(item.Amount) || qty * price;
          const unit = item.UnitOfMeasureName || "";

          return `
            <div class="item">
              <div class="item-name">${description}</div>
              <div class="item-row">
                <span>${qty} ${unit} × ${formatCurrency(price)}</span>
                <span>${formatCurrency(amount)}</span>
              </div>
            </div>
          `;
        })
        .join("");

      /* ---------------------------------------------- */
      /* 5. PRINT WINDOW                                 */
      /* ---------------------------------------------- */

      const printWindow = window.open(
        "",
        "_blank",
        "width=500,height=700"
      );

      if (!printWindow) {
        alert(
          "Print window was blocked by the browser. Please allow pop-ups for this application."
        );
        return;
      }

      printWindow.document.open();

      printWindow.document.write(`
        <!DOCTYPE html>
        <html>
        <head>
          <meta charset="UTF-8" />
          <title>${invoiceTitle} - ${receiptNo}</title>
          <style>
            @page { size: ${paperWidth} auto; margin: 0; }
            * { box-sizing: border-box; }
            html, body {
              width: ${paperWidth};
              margin: 0;
              padding: 0;
              background: white;
            }
            body {
              font-family: Arial, Helvetica, sans-serif;
              font-size: 12px;
              color: #000;
              -webkit-print-color-adjust: exact;
              print-color-adjust: exact;
            }
            .receipt { width: 100%; padding: 4mm; margin: 0; }
            .center { text-align: center; }
            .company-name { font-size: 17px; font-weight: bold; margin-bottom: 2px; }
            .company-info { font-size: 10px; line-height: 1.35; }
            .title { font-size: 15px; font-weight: bold; margin-top: 8px; margin-bottom: 5px; }
            .header-text { font-size: 10px; margin: 4px 0; white-space: pre-line; }
            .line { border-top: 1px dashed #000; margin: 7px 0; }
            .info { font-size: 11px; line-height: 1.5; }
            .info-row { display: flex; justify-content: space-between; gap: 5px; }
            .items { margin-top: 5px; }
            .item { margin-bottom: 6px; }
            .item-name { font-weight: bold; word-break: break-word; }
            .item-row {
              display: flex;
              justify-content: space-between;
              gap: 5px;
              font-size: 11px;
            }
            .total {
              display: flex;
              justify-content: space-between;
              font-size: 15px;
              font-weight: bold;
              margin-top: 5px;
            }
            .footer {
              text-align: center;
              font-size: 10px;
              line-height: 1.4;
              margin-top: 10px;
              white-space: pre-line;
            }
            .duplicate {
              text-align: center;
              font-weight: bold;
              font-size: 13px;
              margin-top: 10px;
              border-top: 1px dashed #000;
              border-bottom: 1px dashed #000;
              padding: 5px 0;
            }
            @media print {
              html, body { width: ${paperWidth}; margin: 0; padding: 0; }
              .receipt { width: 100%; margin: 0; }
            }
          </style>
        </head>
        <body>
          <div class="receipt">
            <div class="center">
              ${companyName ? `<div class="company-name">${companyName}</div>` : ""}
              ${companyAddress ? `<div class="company-info">${companyAddress}</div>` : ""}
              ${companyPhone ? `<div class="company-info">Tel: ${companyPhone}</div>` : ""}
              ${companyEmail ? `<div class="company-info">${companyEmail}</div>` : ""}
              ${
                taxNumber && showTax
                  ? `<div class="company-info">Tax No: ${taxNumber}</div>`
                  : ""
              }
            </div>

            ${
              invoiceHeader
                ? `<div class="header-text center">${invoiceHeader}</div>`
                : ""
            }

            <div class="title center">${invoiceTitle}</div>
            <div class="line"></div>

            <div class="info">
              <div class="info-row"><span>Invoice</span><span>${receiptNo}</span></div>
              ${
                showDateTime
                  ? `<div class="info-row"><span>Date</span><span>${invoiceDate}</span></div>`
                  : ""
              }
              ${
                showCustomer
                  ? `<div class="info-row"><span>Customer</span><span>${customer}</span></div>`
                  : ""
              }
              ${
                showCustomerAddress && invoiceDetails.CustomerAddress
                  ? `<div>Address: ${invoiceDetails.CustomerAddress}</div>`
                  : ""
              }
              ${
                showCustomerPhone && invoiceDetails.CustomerPhone
                  ? `<div>Phone: ${invoiceDetails.CustomerPhone}</div>`
                  : ""
              }
              ${
                showPaymentMethod
                  ? `<div class="info-row"><span>Payment</span><span>${paymentMethod}</span></div>`
                  : ""
              }
              ${
                saleType
                  ? `<div class="info-row"><span>Type</span><span>${saleType}</span></div>`
                  : ""
              }
            </div>

            <div class="line"></div>
            <div class="items">${itemRows}</div>
            <div class="line"></div>

            <div class="total">
              <span>TOTAL</span>
              <span>${formatCurrency(total)}</span>
            </div>

            <div class="info-row" style="margin-top: 4px;">
              <span>Currency</span><span>${currency}</span>
            </div>

            <div class="duplicate">DUPLICATE</div>

            ${invoiceNotes ? `<div class="footer">${invoiceNotes}</div>` : ""}
            ${invoiceFooter ? `<div class="footer">${invoiceFooter}</div>` : ""}
          </div>
        </body>
        </html>
      `);

      printWindow.document.close();

      setTimeout(() => {
        try {
          printWindow.focus();
          printWindow.print();

          setTimeout(() => {
            try {
              printWindow.close();
            } catch (closeError) {
              console.warn(
                "Could not close print window:",
                closeError
              );
            }
          }, 1000);
        } catch (printError) {
          console.error("Print error:", printError);
        }
      }, 400);
    } catch (err) {
      console.error("DIRECT PRINT ERROR:", err);
      alert(
        "Unable to print invoice. Please check POS settings."
      );
    } finally {
      setPrinting(false);
    }
  };

  /* ======================================================
     RENDER
  ====================================================== */

  return (
    <div className="flex h-screen bg-gray-50 overflow-hidden font-sans">
      <div
        className={`flex-1 flex flex-col p-6 overflow-y-auto transition-all duration-300 ${
          selectedInvoice ? "pr-4" : ""
        }`}
      >
        {/* HEADER */}
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            <span className="text-gray-800">📄 Sales History</span>
          </h1>

          <div className="flex gap-2">
            <button
              onClick={loadSales}
              className="flex items-center gap-2 px-4 py-2 bg-white border rounded-lg hover:bg-gray-50"
            >
              <RefreshCw size={16} />
              Refresh
            </button>

            <button className="flex items-center gap-2 px-4 py-2 bg-white border rounded-lg hover:bg-gray-50">
              <Download size={16} />
              Export CSV
            </button>
          </div>
        </div>

        {/* FILTERS */}
        <div className="bg-white p-4 rounded-xl border shadow-sm mb-6 flex flex-wrap gap-4 items-end">
          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1">
              Search
            </label>
            <div className="relative">
              <Search
                size={16}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"
              />
              <input
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="Invoice / customer..."
                className="pl-9 pr-3 py-2 border rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1">
              Payment
            </label>
            <select
              value={payType}
              onChange={(e) => {
                setPayType(e.target.value);
                setPage(1);
              }}
              className="px-3 py-2 border rounded-lg"
            >
              <option>All Payments</option>
              <option>Cash</option>
              <option>Card</option>
              <option>Credit</option>
            </select>
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1">
              Start Date
            </label>
            <div className="relative">
              <Calendar
                size={16}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"
              />
              <input
                type="date"
                value={startDate}
                onChange={(e) => {
                  setStartDate(e.target.value);
                  setPage(1);
                }}
                className="pl-9 pr-3 py-2 border rounded-lg"
              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1">
              End Date
            </label>
            <div className="relative">
              <Calendar
                size={16}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"
              />
              <input
                type="date"
                value={endDate}
                onChange={(e) => {
                  setEndDate(e.target.value);
                  setPage(1);
                }}
                className="pl-9 pr-3 py-2 border rounded-lg"
              />
            </div>
          </div>
        </div>

        {/* ERROR */}
        {error && (
          <div className="mb-4 p-4 bg-red-50 border border-red-200 text-red-700 rounded-lg">
            {error}
          </div>
        )}

        {/* TABLE */}
        <div className="bg-white rounded-xl border shadow-sm flex-1 overflow-hidden flex flex-col">
          <div className="overflow-auto">
            <table className="w-full text-sm">
              <thead className="bg-gray-50 border-b">
                <tr>
                  <th className="text-left px-4 py-3">Invoice</th>
                  <th className="text-left px-4 py-3">Date</th>
                  <th className="text-left px-4 py-3">Customer</th>
                  <th className="text-left px-4 py-3">Payment</th>
                  <th className="text-left px-4 py-3">Type</th>
                  <th className="text-right px-4 py-3">Items</th>
                  <th className="text-right px-4 py-3">Amount</th>
                </tr>
              </thead>

              <tbody>
                {loading ? (
                  <tr>
                    <td
                      colSpan="7"
                      className="text-center py-10 text-gray-500"
                    >
                      Loading...
                    </td>
                  </tr>
                ) : invoices.length === 0 ? (
                  <tr>
                    <td
                      colSpan="7"
                      className="text-center py-10 text-gray-500"
                    >
                      No sales found.
                    </td>
                  </tr>
                ) : (
                  invoices.map((sale) => (
                    <tr
                      key={sale._docId || sale.Receipt}
                      onClick={() => handleRowClick(sale)}
                      className="border-b hover:bg-gray-50 cursor-pointer"
                    >
                      <td className="px-4 py-3 font-medium">
                        {sale.Receipt}
                      </td>
                      <td className="px-4 py-3">
                        {formatDate(sale.RecDate)}
                      </td>
                      <td className="px-4 py-3">
                        {sale.Customer || "Walk-in"}
                      </td>
                      <td className="px-4 py-3">
                        {sale.PayTypeID || "-"}
                      </td>
                      <td className="px-4 py-3">
                        {sale.SaleTypeID || "-"}
                      </td>
                      <td className="px-4 py-3 text-right">
                        {sale.ItemCount || 0}
                      </td>
                      <td className="px-4 py-3 text-right font-medium">
                        {formatCurrency(sale.Amount)}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>

        {/* PAGINATION */}
        <div className="p-4 border-t flex justify-between items-center">
          <span className="text-sm text-gray-500">
            Total Records: {totalRecords}
          </span>

          <div className="flex items-center gap-2">
            <button
              disabled={page <= 1}
              onClick={() => setPage((p) => Math.max(1, p - 1))}
              className="p-2 border rounded-lg disabled:opacity-40"
            >
              <ChevronLeft size={18} />
            </button>

            <span className="text-sm">
              Page {page} of {totalPages}
            </span>

            <button
              disabled={page >= totalPages}
              onClick={() =>
                setPage((p) => Math.min(totalPages, p + 1))
              }
              className="p-2 border rounded-lg disabled:opacity-40"
            >
              <ChevronRight size={18} />
            </button>
          </div>
        </div>
      </div>

      {/* INVOICE DETAILS PANEL */}
      {selectedInvoice && (
        <div className="w-[400px] border-l bg-white shadow-2xl flex flex-col shrink-0">
          <div className="p-5 border-b flex justify-between items-center">
            <div>
              <h2 className="font-bold text-lg">Invoice Details</h2>
              <p className="text-sm text-gray-500">
                {selectedInvoice.Receipt}
              </p>
            </div>

            <div className="flex gap-2">
              <button
                title="Print"
                onClick={handlePrint}
                disabled={
                  loadingDetails || !invoiceDetails || printing
                }
                className={`p-2 rounded-lg border transition ${
                  printing
                    ? "opacity-50 cursor-wait"
                    : "hover:bg-gray-100"
                }`}
              >
                <Printer size={18} />
              </button>

              <button
                title="Edit"
                className="p-2 rounded-lg border hover:bg-gray-100"
              >
                <Edit size={18} />
              </button>

              <button
                onClick={closeDetailsPanel}
                title="Close"
                className="p-2 rounded-lg border hover:bg-gray-100"
              >
                <X size={18} />
              </button>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-5 space-y-6">
            {loadingDetails ? (
              <div className="text-center py-10 text-gray-500">
                Loading invoice...
              </div>
            ) : invoiceDetails ? (
              <>
                <div>
                  <h3 className="font-semibold mb-2">Invoice</h3>
                  <div className="text-sm space-y-1">
                    <div className="flex justify-between">
                      <span className="text-gray-500">Receipt</span>
                      <span>{invoiceDetails.Receipt}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-500">Date</span>
                      <span>
                        {formatDate(invoiceDetails.RecDate)}
                      </span>
                    </div>
                  </div>
                </div>

                <div>
                  <h3 className="font-semibold mb-2">Customer</h3>
                  <div className="text-sm">
                    {invoiceDetails.Customer || "Walk-in Customer"}
                  </div>
                </div>

                <div>
                  <h3 className="font-semibold mb-2">Payment</h3>
                  <div className="text-sm">
                    {invoiceDetails.PaymentMethod || "-"}
                  </div>
                </div>

                <div>
                  <h3 className="font-semibold mb-2">Items</h3>
                  <div className="space-y-3">
                    {invoiceDetails.itemsList?.map((item, idx) => (
                      <div
                        key={item.TransactionDetID || idx}
                        className="border-b pb-2"
                      >
                        <div className="font-medium">{item.Descrip}</div>
                        <div className="flex justify-between text-sm text-gray-500">
                          <span>
                            {item.Qty} {item.UnitOfMeasureName}
                            {" × "}
                            {formatCurrency(item.Price)}
                          </span>
                          <span>{formatCurrency(item.Amount)}</span>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </>
            ) : (
              <div className="text-center py-10 text-red-500">
                Failed to load invoice details.
              </div>
            )}
          </div>

          {invoiceDetails && (
            <div className="p-5 border-t">
              <div className="flex justify-between items-center">
                <span className="font-semibold">Total</span>
                <span className="text-xl font-bold">
                  {formatCurrency(invoiceDetails.TotalAmount)}
                </span>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default SalesHistory;