// src/firebase.js
import { initializeApp, getApps } from "firebase/app";
import { getAuth, setPersistence, browserLocalPersistence } from "firebase/auth";
import {
  initializeFirestore,
  getFirestore,
  persistentLocalCache,
  persistentMultipleTabManager,
} from "firebase/firestore";
import { getStorage } from "firebase/storage";

const firebaseConfig = {
  apiKey: "AIzaSyDIX4Ho-pdWa8RY43f4-5s_rKuH5S3hk-U",
  authDomain: "mpos-88c6b.firebaseapp.com",
  projectId: "mpos-88c6b",
  storageBucket: "mpos-88c6b.firebasestorage.app",
  messagingSenderId: "554927337186",
  appId: "1:554927337186:web:0fd3def34a1263631ab8bb",
  measurementId: "G-K36RJDV3LF",
};

const isFirstInit = !getApps().length;
const app = isFirstInit ? initializeApp(firebaseConfig) : getApps()[0];

export const auth = getAuth(app);
export const storage = getStorage(app);

// Resolve once auth persistence is configured. Consumers that need the
// restored `auth.currentUser` before subscribing (e.g. AuthContext) can
// `await authReady` first, which avoids the "one null emission before the
// restored user" race that makes PermissionsProvider fall back to a stale
// legacy CashierID.
export const authReady = setPersistence(auth, browserLocalPersistence)
  .then(() => {
    console.info("[firebase] auth persistence = browserLocalPersistence");
  })
  .catch((err) => {
    console.warn(
      "[firebase] could not set auth persistence; session may not survive reload:",
      err?.code || err?.message
    );
  });

// Firestore must be initialized with persistence exactly ONCE per app.
// `initializeFirestore` throws if Firestore has already been started on this
// app — HMR, hot reload, or another module that called getFirestore first.
// We catch it so the module doesn't crash, but log loudly: without
// persistence, getDocsFromCache() returns empty and the offline permission
// fallback will not work.
//
// IMPORTANT: grep your codebase once for `getFirestore(` outside this file
// and remove those calls. Any of them racing this one will silently disable
// persistence and reproduce the "Network unreachable and no cache available"
// warning.
let dbInstance;
try {
  dbInstance = initializeFirestore(app, {
    localCache: persistentLocalCache({
      tabManager: persistentMultipleTabManager(),
    }),
  });
  console.info(
    "[firebase] Firestore persistence ENABLED (persistentLocalCache + multi-tab)"
  );
} catch (err) {
  dbInstance = getFirestore(app);
  console.warn(
    "[firebase] initializeFirestore fell back to in-memory cache — offline reads will NOT work. " +
      "Grep for other `getFirestore(` calls outside this file and remove them.",
    err?.code || err?.message
  );
}

export const db = dbInstance;
export default app;